import type { Lesson } from "./types.ts"
export const COURSE: Lesson[] = [{"id":1,"title":"Сказать «люблю», «не люблю» и спросить","goal":"Одними и теми же словами сказать, что любите и что едите: сейчас, вчера и завтра, да, нет и вопрос.","petrov":"Первый шаг Петрова: одна таблица на одном глаголе. Утверждение, отрицание и вопрос. Время не окончание, а слово в начале, поэтому «любил» и «буду любить» входят сразу.","formula":"Кто, потом действие, потом кого. Время в начале. ไม่ прямо перед действием. ไม่ได้ перед действием значит «не сделал». จะ перед действием значит «собираюсь». ไหม в самом конце, перед вежливым словом. Глагол во всех клетках один и тот же.","note":"Для «любил» тайцы оставляют тот же глагол и ставят เมื่อวาน. แล้ว сюда не входит: это не прошедшее время. С любовью иногда говорят и просто เมื่อวานไม่รัก. В таблице одно отрицание прошлого, ไม่ได้, чтобы «не ел» потом собиралось так же. В быстрой речи слог ได้ перед глаголом короче, тон тот же падающий.","lead":{"ru":"Я люблю тебя.","m":{"th":"ผมรักคุณครับ","rom":"phǒm rák khun khráp"},"f":{"th":"ฉันรักคุณค่ะ","rom":"chǎn rák khun khâ"}},"words":[{"th":"ผม","rom":"phǒm","ru":"я, мужской род","how":"Две буквы, гласной между ними на письме нет. ผ читается ph: п с выдохом. ม закрывает слог на м. Между ними краткое о. ผ высокого класса, слог живой, знака тона нет. Тон восходящий: phǒm."},{"th":"ฉัน","rom":"chǎn","ru":"я, женский род","how":"ฉ читается ch: ч с выдохом. ั это краткое а. น на конце н. Высокий класс, слог живой, знака нет. Тон восходящий: chǎn."},{"th":"คุณ","rom":"khun","ru":"вы","how":"ค читается kh: к с выдохом. ุ краткое у. ณ это н. Низкий класс, слог живой, знака нет. Тон средний: khun."},{"th":"รัก","rom":"rák","ru":"любить","how":"ร это r. ั краткое а. ก на конце глухое к, его не взрывают. Знака тона нет. Низкий класс и короткий слог на глухой дают высокий тон: rák. Глагол вчера и завтра не меняется."},{"th":"กิน","rom":"gin","ru":"есть","how":"ก читается g: к без выдоха, не kh. ิ краткое и. น это н. Средний класс, слог живой. Тон средний: gin."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."},{"th":"ไหม","rom":"mǎi","ru":"ли, вопрос да или нет","how":"ห не читается: она только переводит слог в высокий класс. Звук начинается с м, гласный тот же ai, что в ไม่. Знака тона нет. Высокий класс и живой слог дают восходящий тон: mǎi. Стоит в конце фразы, перед ครับ khráp или คะ khá. С падающим ไม่ это разные слова."},{"th":"ได้","rom":"dâai","ru":"получилось; в ไม่ได้ меняет смысл от места","how":"ไ слева, гласный ai. ด это d. ้ это май-тхо. Средний класс плюс май-тхо дают падающий тон: dâai. Перед действием ไม่ได้ значит «не сделал». После действия ได้ значит «могу», ไม่ได้ значит «не могу»."},{"th":"จะ","rom":"jà","ru":"собираюсь, будет","how":"จ это j. ะ краткое а. Знака тона нет. Средний класс и короткий слог без конечной согласной дают низкий тон: jà. Стоит перед действием. Это не окончание глагола."},{"th":"เมื่อวาน","rom":"mʉ̂ʉa-waan","ru":"вчера","how":"Когда: เ, ื и อ вместе дают гласный ʉa, ม это м, ่ май-эк. Низкий класс плюс май-эк: падающий mʉ̂ʉa. วาน: ว это w, า долгое а, น это н. Низкий класс, живой слог, знака нет: средний waan. Всё слово ставьте в начало фразы."},{"th":"พรุ่งนี้","rom":"phrûng-níi","ru":"завтра","how":"พ это ph с выдохом. ร в речи часто почти не слышно. ุ краткое у, ่ май-эк, ง это нг. Низкий класс плюс май-эк: падающий phrûng. Второй слог นี้ пишется с ้ май-тхо: น это н, ี долгое и. Низкий класс плюс май-тхо: высокий níi. Не читайте второй слог падающим."},{"th":"ครับ","rom":"khráp","ru":"вежливое слово мужчины","how":"ค это kh. ร в речи обычно выпадает, слышится káp. ั краткое а. บ на конце глухое п. Низкий класс и короткий глухой слог дают высокий тон. Мужчина ставит это и после утверждения, и после вопроса."},{"th":"ค่ะ","rom":"khâ","ru":"вежливое слово женщины в утверждении","how":"ค это kh, ่ май-эк, ะ краткое а. Низкий класс плюс май-эк: падающий khâ. Женщина закрывает так утверждение, не вопрос."},{"th":"คะ","rom":"khá","ru":"вежливое слово женщины в вопросе","how":"Те же ค и краткое а, знака тона нет. Короткий глухой слог низкого класса даёт высокий тон: khá. Женщина закрывает так вопрос."}],"diagrams":[{"title":"Фраза, которую вы уже сказали","slots":[{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"действие","m":{"th":"รัก","rom":"rák"},"f":{"th":"รัก","rom":"rák"}},{"role":"кого","m":{"th":"คุณ","rom":"khun"},"f":{"th":"คุณ","rom":"khun"}},{"role":"вежливо","m":{"th":"ครับ","rom":"khráp"},"f":{"th":"ค่ะ","rom":"khâ"}}]},{"title":"Вчера не любил: те же слова","slots":[{"role":"когда","m":{"th":"เมื่อวาน","rom":"mʉ̂ʉa-waan"},"f":{"th":"เมื่อวาน","rom":"mʉ̂ʉa-waan"}},{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"не сделал","m":{"th":"ไม่ได้","rom":"mâi-dâai"},"f":{"th":"ไม่ได้","rom":"mâi-dâai"}},{"role":"действие","m":{"th":"รัก","rom":"rák"},"f":{"th":"รัก","rom":"rák"}},{"role":"кого","m":{"th":"คุณ","rom":"khun"},"f":{"th":"คุณ","rom":"khun"}},{"role":"вежливо","m":{"th":"ครับ","rom":"khráp"},"f":{"th":"ค่ะ","rom":"khâ"}}]},{"title":"Завтра спросят вас","slots":[{"role":"когда","m":{"th":"พรุ่งนี้","rom":"phrûng-níi"},"f":{"th":"พรุ่งนี้","rom":"phrûng-níi"}},{"role":"кто","m":{"th":"คุณ","rom":"khun"},"f":{"th":"คุณ","rom":"khun"}},{"role":"соберусь","m":{"th":"จะ","rom":"jà"},"f":{"th":"จะ","rom":"jà"}},{"role":"действие","m":{"th":"รัก","rom":"rák"},"f":{"th":"รัก","rom":"rák"}},{"role":"кого","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"ли","m":{"th":"ไหม","rom":"mǎi"},"f":{"th":"ไหม","rom":"mǎi"}},{"role":"вежливо","m":{"th":"ครับ","rom":"khráp"},"f":{"th":"คะ","rom":"khá"}}]}],"tables":[{"title":"Любить: девять клеток","cols":["да","нет","вопрос"],"rows":[{"h":"сейчас","cells":[{"ru":"Я люблю тебя.","m":{"th":"ผมรักคุณครับ","rom":"phǒm rák khun khráp"},"f":{"th":"ฉันรักคุณค่ะ","rom":"chǎn rák khun khâ"}},{"ru":"Я не люблю тебя.","m":{"th":"ผมไม่รักคุณครับ","rom":"phǒm mâi rák khun khráp"},"f":{"th":"ฉันไม่รักคุณค่ะ","rom":"chǎn mâi rák khun khâ"}},{"ru":"Ты любишь меня?","m":{"th":"คุณรักผมไหมครับ","rom":"khun rák phǒm mǎi khráp"},"f":{"th":"คุณรักฉันไหมคะ","rom":"khun rák chǎn mǎi khá"}}]},{"h":"вчера","cells":[{"ru":"Вчера я любил тебя.","m":{"th":"เมื่อวานผมรักคุณครับ","rom":"mʉ̂ʉa-waan phǒm rák khun khráp"},"f":{"th":"เมื่อวานฉันรักคุณค่ะ","rom":"mʉ̂ʉa-waan chǎn rák khun khâ"}},{"ru":"Вчера я не любил тебя.","m":{"th":"เมื่อวานผมไม่ได้รักคุณครับ","rom":"mʉ̂ʉa-waan phǒm mâi-dâai rák khun khráp"},"f":{"th":"เมื่อวานฉันไม่ได้รักคุณค่ะ","rom":"mʉ̂ʉa-waan chǎn mâi-dâai rák khun khâ"}},{"ru":"Вчера ты любил меня?","m":{"th":"เมื่อวานคุณรักผมไหมครับ","rom":"mʉ̂ʉa-waan khun rák phǒm mǎi khráp"},"f":{"th":"เมื่อวานคุณรักฉันไหมคะ","rom":"mʉ̂ʉa-waan khun rák chǎn mǎi khá"}}]},{"h":"завтра","cells":[{"ru":"Завтра я буду любить тебя.","m":{"th":"พรุ่งนี้ผมจะรักคุณครับ","rom":"phrûng-níi phǒm jà rák khun khráp"},"f":{"th":"พรุ่งนี้ฉันจะรักคุณค่ะ","rom":"phrûng-níi chǎn jà rák khun khâ"}},{"ru":"Завтра я не буду любить тебя.","m":{"th":"พรุ่งนี้ผมจะไม่รักคุณครับ","rom":"phrûng-níi phǒm jà mâi rák khun khráp"},"f":{"th":"พรุ่งนี้ฉันจะไม่รักคุณค่ะ","rom":"phrûng-níi chǎn jà mâi rák khun khâ"}},{"ru":"Завтра ты будешь любить меня?","m":{"th":"พรุ่งนี้คุณจะรักผมไหมครับ","rom":"phrûng-níi khun jà rák phǒm mǎi khráp"},"f":{"th":"พรุ่งนี้คุณจะรักฉันไหมคะ","rom":"phrûng-níi khun jà rák chǎn mǎi khá"}}]}]},{"title":"Есть: те же клетки, другое действие","cols":["да","нет","вопрос"],"rows":[{"h":"сейчас","cells":[{"ru":"Я ем.","m":{"th":"ผมกินครับ","rom":"phǒm gin khráp"},"f":{"th":"ฉันกินค่ะ","rom":"chǎn gin khâ"}},{"ru":"Я не ем.","m":{"th":"ผมไม่กินครับ","rom":"phǒm mâi gin khráp"},"f":{"th":"ฉันไม่กินค่ะ","rom":"chǎn mâi gin khâ"}},{"ru":"Ты ешь?","m":{"th":"คุณกินไหมครับ","rom":"khun gin mǎi khráp"},"f":{"th":"คุณกินไหมคะ","rom":"khun gin mǎi khá"}}]},{"h":"вчера","cells":[{"ru":"Вчера я ел.","m":{"th":"เมื่อวานผมกินครับ","rom":"mʉ̂ʉa-waan phǒm gin khráp"},"f":{"th":"เมื่อวานฉันกินค่ะ","rom":"mʉ̂ʉa-waan chǎn gin khâ"}},{"ru":"Вчера я не ел.","m":{"th":"เมื่อวานผมไม่ได้กินครับ","rom":"mʉ̂ʉa-waan phǒm mâi-dâai gin khráp"},"f":{"th":"เมื่อวานฉันไม่ได้กินค่ะ","rom":"mʉ̂ʉa-waan chǎn mâi-dâai gin khâ"}},{"ru":"Вчера ты ел?","m":{"th":"เมื่อวานคุณกินไหมครับ","rom":"mʉ̂ʉa-waan khun gin mǎi khráp"},"f":{"th":"เมื่อวานคุณกินไหมคะ","rom":"mʉ̂ʉa-waan khun gin mǎi khá"}}]},{"h":"завтра","cells":[{"ru":"Завтра я буду есть.","m":{"th":"พรุ่งนี้ผมจะกินครับ","rom":"phrûng-níi phǒm jà gin khráp"},"f":{"th":"พรุ่งนี้ฉันจะกินค่ะ","rom":"phrûng-níi chǎn jà gin khâ"}},{"ru":"Завтра я не буду есть.","m":{"th":"พรุ่งนี้ผมจะไม่กินครับ","rom":"phrûng-níi phǒm jà mâi gin khráp"},"f":{"th":"พรุ่งนี้ฉันจะไม่กินค่ะ","rom":"phrûng-níi chǎn jà mâi gin khâ"}},{"ru":"Завтра ты будешь есть?","m":{"th":"พรุ่งนี้คุณจะกินไหมครับ","rom":"phrûng-níi khun jà gin mǎi khráp"},"f":{"th":"พรุ่งนี้คุณจะกินไหมคะ","rom":"phrûng-níi khun jà gin mǎi khá"}}]}]}],"drills":[{"ru":"Я люблю тебя.","m":{"th":"ผมรักคุณครับ","rom":"phǒm rák khun khráp"},"f":{"th":"ฉันรักคุณค่ะ","rom":"chǎn rák khun khâ"}},{"ru":"Я не люблю тебя.","m":{"th":"ผมไม่รักคุณครับ","rom":"phǒm mâi rák khun khráp"},"f":{"th":"ฉันไม่รักคุณค่ะ","rom":"chǎn mâi rák khun khâ"}},{"ru":"Ты любишь меня?","m":{"th":"คุณรักผมไหมครับ","rom":"khun rák phǒm mǎi khráp"},"f":{"th":"คุณรักฉันไหมคะ","rom":"khun rák chǎn mǎi khá"}},{"ru":"Вчера я не любил тебя.","m":{"th":"เมื่อวานผมไม่ได้รักคุณครับ","rom":"mʉ̂ʉa-waan phǒm mâi-dâai rák khun khráp"},"f":{"th":"เมื่อวานฉันไม่ได้รักคุณค่ะ","rom":"mʉ̂ʉa-waan chǎn mâi-dâai rák khun khâ"}},{"ru":"Завтра я буду любить тебя.","m":{"th":"พรุ่งนี้ผมจะรักคุณครับ","rom":"phrûng-níi phǒm jà rák khun khráp"},"f":{"th":"พรุ่งนี้ฉันจะรักคุณค่ะ","rom":"phrûng-níi chǎn jà rák khun khâ"}},{"ru":"Завтра ты будешь любить меня?","m":{"th":"พรุ่งนี้คุณจะรักผมไหมครับ","rom":"phrûng-níi khun jà rák phǒm mǎi khráp"},"f":{"th":"พรุ่งนี้คุณจะรักฉันไหมคะ","rom":"phrûng-níi khun jà rák chǎn mǎi khá"}},{"ru":"Вчера я не ел.","m":{"th":"เมื่อวานผมไม่ได้กินครับ","rom":"mʉ̂ʉa-waan phǒm mâi-dâai gin khráp"},"f":{"th":"เมื่อวานฉันไม่ได้กินค่ะ","rom":"mʉ̂ʉa-waan chǎn mâi-dâai gin khâ"}},{"ru":"Завтра я не буду есть.","m":{"th":"พรุ่งนี้ผมจะไม่กินครับ","rom":"phrûng-níi phǒm jà mâi gin khráp"},"f":{"th":"พรุ่งนี้ฉันจะไม่กินค่ะ","rom":"phrûng-níi chǎn jà mâi gin khâ"}}],"self":"Пройдите девять клеток вслух про человека, которому хотите это сказать, и про еду, которую едите. Глагол не меняйте. Меняются только время, нет и вопрос."},{"id":2,"title":"Спросить, кто, что, куда и когда","goal":"Спросить и ответить теми же глаголами: кто, что, куда, где, когда и почему.","petrov":"Второй шаг Петрова: вопросительные слова. В тайском они стоят на месте ответа. Порядок фразы не переворачивается, и ไหม к ним не добавляется.","formula":"Кто ест: ใคร на месте подлежащего. Что едите: อะไร на месте объекта. Куда: ไปไหน. Где: ที่ไหน на месте места. Когда: เมื่อไหร่ на месте времени. Почему: ทำไม в начале. ไหม здесь нет.","note":"Ответ собирается из слов первого урока плюс рис, дом и «с». Короткий ответ можно дать одним словом, полный ответ закрывайте ครับ khráp или ค่ะ khâ.","lead":{"ru":"Что ты ешь?","m":{"th":"คุณกินอะไรครับ","rom":"khun gin à-rai khráp"},"f":{"th":"คุณกินอะไรคะ","rom":"khun gin à-rai khá"}},"words":[{"th":"อะไร","rom":"à-rai","ru":"что","how":"Два слога. อะ: อ среднего класса и краткое а без конечной согласной, знака нет, тон низкий à. ไร: ร это r, ไ гласный ai. Низкий класс, живой слог, знака нет, тон средний rai. Вопрос «что» стоит на месте ответа: คุณกินอะไร «вы едите что»."},{"th":"ใคร","rom":"khrai","ru":"кто","how":"ค это kh. ใ гласный ai, пишется слева. ร на конце почти не слышно отдельным звуком. Низкий класс, живой слог, знака нет. Тон средний: khrai. Стоит там, где стоял бы ответ: в «кто ест» это начало фразы."},{"th":"ไหน","rom":"nǎi","ru":"какой, где, в составе куда","how":"ห не читается и делает класс высоким. Звук начинается с н, ไ это ai. Знака нет, живой слог высокого класса: восходящий nǎi. В ไปไหน получается «куда»."},{"th":"ที่","rom":"thîi","ru":"место; также служебное слово","how":"ท это th: т с выдохом, не английское think. ี долгое и. ่ май-эк. Низкий класс плюс май-эк: падающий thîi."},{"th":"ที่ไหน","rom":"thîi-nǎi","ru":"где","how":"Складывается из ที่ thîi, падающий, и ไหน nǎi, восходящий. ห во втором слоге не читается. Стоит на месте ответа: คุณกินที่ไหน «вы едите где»."},{"th":"เมื่อไหร่","rom":"mʉ̂ʉa-rài","ru":"когда","how":"เมื่อ как во вчера: падающий mʉ̂ʉa. ไหร่: ห не читается, звук с r, ่ май-эк, гласный ai. Высокий класс плюс май-эк: низкий rài. Стоит на месте ответа: คุณไปเมื่อไหร่ «вы идёте когда»."},{"th":"ทำไม","rom":"tham-mai","ru":"почему","how":"ทำ: ท это th, ำ это am. Низкий класс, живой слог, знака нет: средний tham. ไม: ม это м, ไ это ai, знака нет, низкий класс, живой слог: средний mai. Оба средних. «Почему» обычно стоит в начале."},{"th":"เขา","rom":"khǎo","ru":"он, она, они","how":"ข это kh с выдохом, высокий класс. เ и า вместе дают гласный ao. Знака нет, живой слог: восходящий khǎo. Одно слово на «он», «она» и «они»."},{"th":"เรา","rom":"rao","ru":"мы","how":"ร это r, низкий класс. เ и า дают ao. Знака нет, живой слог: средний rao."},{"th":"ไป","rom":"bpai","ru":"идти, ехать туда","how":"ป читается bp: п без выдоха, один звук. ไ гласный ai. Средний класс, живой слог, знака нет: средний bpai."},{"th":"มา","rom":"maa","ru":"приходить, сюда","how":"ม это м, низкий класс. า долгое а. Знака нет, живой слог: средний maa. Рядом с другим глаголом показывает направление к говорящему."},{"th":"กับ","rom":"gàp","ru":"с","how":"ก это g без выдоха. ั краткое а. บ на конце глухое п. Знака нет. Средний класс и короткий глухой слог дают низкий тон: gàp."},{"th":"ข้าว","rom":"khâao","ru":"рис, еда","how":"ข это kh, высокий класс. ้ май-тхо. า долгое а, ว достраивает гласный ao. Высокий класс плюс май-тхо: падающий khâao."},{"th":"บ้าน","rom":"bâan","ru":"дом","how":"บ это b, средний класс. ้ май-тхо. า долгое а. น это н. Средний класс плюс май-тхо: падающий bâan."},{"th":"กิน","rom":"gin","ru":"есть","how":"ก читается g: к без выдоха, не kh. ิ краткое и. น это н. Средний класс, слог живой. Тон средний: gin."},{"th":"คุณ","rom":"khun","ru":"вы","how":"ค читается kh: к с выдохом. ุ краткое у. ณ это н. Низкий класс, слог живой, знака нет. Тон средний: khun."},{"th":"ผม","rom":"phǒm","ru":"я, мужской род","how":"Две буквы, гласной между ними на письме нет. ผ читается ph: п с выдохом. ม закрывает слог на м. Между ними краткое о. ผ высокого класса, слог живой, знака тона нет. Тон восходящий: phǒm."},{"th":"ฉัน","rom":"chǎn","ru":"я, женский род","how":"ฉ читается ch: ч с выдохом. ั это краткое а. น на конце н. Высокий класс, слог живой, знака нет. Тон восходящий: chǎn."},{"th":"พรุ่งนี้","rom":"phrûng-níi","ru":"завтра","how":"พ это ph с выдохом. ร в речи часто почти не слышно. ุ краткое у, ่ май-эк, ง это нг. Низкий класс плюс май-эк: падающий phrûng. Второй слог นี้ пишется с ้ май-тхо: น это н, ี долгое и. Низкий класс плюс май-тхо: высокий níi. Не читайте второй слог падающим."}],"diagrams":[{"title":"Вопрос стоит на месте ответа","slots":[{"role":"кто","m":{"th":"คุณ","rom":"khun"},"f":{"th":"คุณ","rom":"khun"}},{"role":"действие","m":{"th":"กิน","rom":"gin"},"f":{"th":"กิน","rom":"gin"}},{"role":"что","m":{"th":"อะไร","rom":"à-rai"},"f":{"th":"อะไร","rom":"à-rai"}},{"role":"вежливо","m":{"th":"ครับ","rom":"khráp"},"f":{"th":"คะ","rom":"khá"}}]}],"tables":[{"title":"Спросить про еду и про дорогу","cols":["вопрос","ответ"],"rows":[{"h":"что","cells":[{"ru":"Что ты ешь?","m":{"th":"คุณกินอะไรครับ","rom":"khun gin à-rai khráp"},"f":{"th":"คุณกินอะไรคะ","rom":"khun gin à-rai khá"}},{"ru":"Я ем рис.","m":{"th":"ผมกินข้าวครับ","rom":"phǒm gin khâao khráp"},"f":{"th":"ฉันกินข้าวค่ะ","rom":"chǎn gin khâao khâ"}}]},{"h":"кто","cells":[{"ru":"Кто ест?","m":{"th":"ใครกินครับ","rom":"khrai gin khráp"},"f":{"th":"ใครกินคะ","rom":"khrai gin khá"}},{"ru":"Я ем.","m":{"th":"ผมกินครับ","rom":"phǒm gin khráp"},"f":{"th":"ฉันกินค่ะ","rom":"chǎn gin khâ"}}]},{"h":"где","cells":[{"ru":"Где ты ешь?","m":{"th":"คุณกินที่ไหนครับ","rom":"khun gin thîi-nǎi khráp"},"f":{"th":"คุณกินที่ไหนคะ","rom":"khun gin thîi-nǎi khá"}},{"ru":"Я ем дома.","m":{"th":"ผมกินที่บ้านครับ","rom":"phǒm gin thîi bâan khráp"},"f":{"th":"ฉันกินที่บ้านค่ะ","rom":"chǎn gin thîi bâan khâ"}}]},{"h":"куда","cells":[{"ru":"Куда ты идёшь?","m":{"th":"คุณไปไหนครับ","rom":"khun bpai nǎi khráp"},"f":{"th":"คุณไปไหนคะ","rom":"khun bpai nǎi khá"}},{"ru":"Я иду домой.","m":{"th":"ผมไปบ้านครับ","rom":"phǒm bpai bâan khráp"},"f":{"th":"ฉันไปบ้านค่ะ","rom":"chǎn bpai bâan khâ"}}]},{"h":"когда","cells":[{"ru":"Когда ты идёшь?","m":{"th":"คุณไปเมื่อไหร่ครับ","rom":"khun bpai mʉ̂ʉa-rài khráp"},"f":{"th":"คุณไปเมื่อไหร่คะ","rom":"khun bpai mʉ̂ʉa-rài khá"}},{"ru":"Я иду завтра.","m":{"th":"พรุ่งนี้ผมไปครับ","rom":"phrûng-níi phǒm bpai khráp"},"f":{"th":"พรุ่งนี้ฉันไปค่ะ","rom":"phrûng-níi chǎn bpai khâ"}}]},{"h":"почему","cells":[{"ru":"Почему ты не ешь?","m":{"th":"ทำไมคุณไม่กินครับ","rom":"tham-mai khun mâi gin khráp"},"f":{"th":"ทำไมคุณไม่กินคะ","rom":"tham-mai khun mâi gin khá"}},{"ru":"Я не ем.","m":{"th":"ผมไม่กินครับ","rom":"phǒm mâi gin khráp"},"f":{"th":"ฉันไม่กินค่ะ","rom":"chǎn mâi gin khâ"}}]},{"h":"с кем","cells":[{"ru":"С кем ты пришёл?","m":{"th":"คุณมากับใครครับ","rom":"khun maa gàp khrai khráp"},"f":{"th":"คุณมากับใครคะ","rom":"khun maa gàp khrai khá"}},{"ru":"Я пришёл с ним.","m":{"th":"ผมมากับเขาครับ","rom":"phǒm maa gàp khǎo khráp"},"f":{"th":"ฉันมากับเขาค่ะ","rom":"chǎn maa gàp khǎo khâ"}}]}]}],"drills":[{"ru":"Что ты ешь?","m":{"th":"คุณกินอะไรครับ","rom":"khun gin à-rai khráp"},"f":{"th":"คุณกินอะไรคะ","rom":"khun gin à-rai khá"}},{"ru":"Я ем рис.","m":{"th":"ผมกินข้าวครับ","rom":"phǒm gin khâao khráp"},"f":{"th":"ฉันกินข้าวค่ะ","rom":"chǎn gin khâao khâ"}},{"ru":"Кто ест?","m":{"th":"ใครกินครับ","rom":"khrai gin khráp"},"f":{"th":"ใครกินคะ","rom":"khrai gin khá"}},{"ru":"Куда ты идёшь?","m":{"th":"คุณไปไหนครับ","rom":"khun bpai nǎi khráp"},"f":{"th":"คุณไปไหนคะ","rom":"khun bpai nǎi khá"}},{"ru":"Я иду домой.","m":{"th":"ผมไปบ้านครับ","rom":"phǒm bpai bâan khráp"},"f":{"th":"ฉันไปบ้านค่ะ","rom":"chǎn bpai bâan khâ"}},{"ru":"Когда ты идёшь?","m":{"th":"คุณไปเมื่อไหร่ครับ","rom":"khun bpai mʉ̂ʉa-rài khráp"},"f":{"th":"คุณไปเมื่อไหร่คะ","rom":"khun bpai mʉ̂ʉa-rài khá"}},{"ru":"Где ты ешь?","m":{"th":"คุณกินที่ไหนครับ","rom":"khun gin thîi-nǎi khráp"},"f":{"th":"คุณกินที่ไหนคะ","rom":"khun gin thîi-nǎi khá"}},{"ru":"Почему ты не ешь?","m":{"th":"ทำไมคุณไม่กินครับ","rom":"tham-mai khun mâi gin khráp"},"f":{"th":"ทำไมคุณไม่กินคะ","rom":"tham-mai khun mâi gin khá"}},{"ru":"С кем ты пришёл?","m":{"th":"คุณมากับใครครับ","rom":"khun maa gàp khrai khráp"},"f":{"th":"คุณมากับใครคะ","rom":"khun maa gàp khrai khá"}}],"self":"Спросите вслух шесть вопросов про сегодняшний день: что ели, где, с кем, куда идёте, когда и почему. Потом ответьте на них про себя."},{"id":3,"title":"Сказать, кто я, где я и что мне нравится","goal":"Сказать роль, место, голод, что нравится и чего хотите. И сказать, что вы не врач и не учитель.","petrov":"Третий шаг Петрова: быть, место, нравиться и хотеть. В тайском это четыре разные сборки, не один глагол «быть».","formula":"Роль: เป็น. Место: อยู่. Состояние и оценка: вообще без связки, ผมหิว. Нравится: ชอบ. Хочу: อยาก перед действием. «Я не учитель» собирается через ไม่ใช่, не через ไม่เป็น.","note":"มี «имеется» будет отдельным уроком, когда скажете, что есть и чего нет. Здесь его не подставляйте вместо เป็น.","lead":{"ru":"Я учитель.","m":{"th":"ผมเป็นครูครับ","rom":"phǒm bpen khruu khráp"},"f":{"th":"ฉันเป็นครูค่ะ","rom":"chǎn bpen khruu khâ"}},"words":[{"th":"เป็น","rom":"bpen","ru":"являться кем-то, роль","how":"ป это bp без выдоха. เ и ็ дают краткое э. น это н. Средний класс, живой слог: средний bpen. Этим говорят профессию и роль. «Я не врач» так не отрицается."},{"th":"อยู่","rom":"yùu","ru":"находиться","how":"Первая буква อ не даёт отдельного слога: она задаёт средний класс, звук начинается с ย, это y. ู долгое у. ่ май-эк. Средний класс плюс май-эк: низкий yùu. Место стоит после: อยู่บ้าน «дома»."},{"th":"ชอบ","rom":"chɔ̂ɔp","ru":"нравится","how":"ช это ch. อ долгое открытое о. บ на конце глухое п. Знака тона нет. Низкий класс и долгий глухой слог дают падающий тон: chɔ̂ɔp."},{"th":"อยาก","rom":"yàak","ru":"хотеть","how":"อ задаёт средний класс, звук начинается с ย. า долгое а. ก на конце глухое к. Знака нет. Средний класс и долгий глухой слог дают низкий тон: yàak. Перед другим действием: อยากกิน «хочу есть»."},{"th":"หิว","rom":"hǐu","ru":"голодный","how":"ห это h, высокий класс, здесь она слышна. ิ краткое и. ว закрывает слог на w. Знака нет, живой слог высокого класса: восходящий hǐu. Перед ним нет связки: ผมหิว «я голоден»."},{"th":"ครู","rom":"khruu","ru":"учитель","how":"ค это kh. ร в речи слабое. ู долгое у. Низкий класс, живой слог, знака нет: средний khruu."},{"th":"หมอ","rom":"mɔ̌ɔ","ru":"врач","how":"ห не читается и делает класс высоким. Звук начинается с м. อ долгое открытое о. Знака нет, живой слог: восходящий mɔ̌ɔ."},{"th":"ไม่ใช่","rom":"mâi-châi","ru":"это не так, я не тот","how":"ไม่ mâi, падающий, плюс ใช่. ใช่: ช это ch, ใ гласный ai, ่ май-эк. Низкий класс плюс май-эк: падающий châi. Вместе «не является». Так отрицают роль: ผมไม่ใช่หมอ «я не врач»."},{"th":"ใช่","rom":"châi","ru":"да, это так","how":"ช это ch. ใ гласный ai. ่ май-эк. Низкий класс плюс май-эк: падающий châi. На вопрос с ใช่ไหม отвечают ใช่ или ไม่ใช่. На вопрос с глаголом и ไหม повторяют глагол."},{"th":"บ้าน","rom":"bâan","ru":"дом","how":"บ это b, средний класс. ้ май-тхо. า долгое а. น это н. Средний класс плюс май-тхо: падающий bâan."},{"th":"ข้าว","rom":"khâao","ru":"рис, еда","how":"ข это kh, высокий класс. ้ май-тхо. า долгое а, ว достраивает гласный ao. Высокий класс плюс май-тхо: падающий khâao."},{"th":"กิน","rom":"gin","ru":"есть","how":"ก читается g: к без выдоха, не kh. ิ краткое и. น это н. Средний класс, слог живой. Тон средний: gin."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."}],"diagrams":[{"title":"Роль","slots":[{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"роль","m":{"th":"เป็น","rom":"bpen"},"f":{"th":"เป็น","rom":"bpen"}},{"role":"кем","m":{"th":"ครู","rom":"khruu"},"f":{"th":"ครู","rom":"khruu"}}]},{"title":"Это не я","slots":[{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"не тот","m":{"th":"ไม่ใช่","rom":"mâi-châi"},"f":{"th":"ไม่ใช่","rom":"mâi-châi"}},{"role":"кем","m":{"th":"หมอ","rom":"mɔ̌ɔ"},"f":{"th":"หมอ","rom":"mɔ̌ɔ"}}]}],"tables":[{"title":"Одна таблица на каждую сборку","cols":["да","нет","вопрос"],"rows":[{"h":"роль","cells":[{"ru":"Я учитель.","m":{"th":"ผมเป็นครูครับ","rom":"phǒm bpen khruu khráp"},"f":{"th":"ฉันเป็นครูค่ะ","rom":"chǎn bpen khruu khâ"}},{"ru":"Я не врач.","m":{"th":"ผมไม่ใช่หมอครับ","rom":"phǒm mâi-châi mɔ̌ɔ khráp"},"f":{"th":"ฉันไม่ใช่หมอค่ะ","rom":"chǎn mâi-châi mɔ̌ɔ khâ"}},{"ru":"Ты учитель?","m":{"th":"คุณเป็นครูไหมครับ","rom":"khun bpen khruu mǎi khráp"},"f":{"th":"คุณเป็นครูไหมคะ","rom":"khun bpen khruu mǎi khá"}}]},{"h":"место","cells":[{"ru":"Я дома.","m":{"th":"ผมอยู่บ้านครับ","rom":"phǒm yùu bâan khráp"},"f":{"th":"ฉันอยู่บ้านค่ะ","rom":"chǎn yùu bâan khâ"}},{"ru":"Я не дома.","m":{"th":"ผมไม่อยู่บ้านครับ","rom":"phǒm mâi yùu bâan khráp"},"f":{"th":"ฉันไม่อยู่บ้านค่ะ","rom":"chǎn mâi yùu bâan khâ"}},{"ru":"Ты дома?","m":{"th":"คุณอยู่บ้านไหมครับ","rom":"khun yùu bâan mǎi khráp"},"f":{"th":"คุณอยู่บ้านไหมคะ","rom":"khun yùu bâan mǎi khá"}}]},{"h":"состояние","cells":[{"ru":"Я голоден.","m":{"th":"ผมหิวครับ","rom":"phǒm hǐu khráp"},"f":{"th":"ฉันหิวค่ะ","rom":"chǎn hǐu khâ"}},{"ru":"Я не голоден.","m":{"th":"ผมไม่หิวครับ","rom":"phǒm mâi hǐu khráp"},"f":{"th":"ฉันไม่หิวค่ะ","rom":"chǎn mâi hǐu khâ"}},{"ru":"Ты голоден?","m":{"th":"คุณหิวไหมครับ","rom":"khun hǐu mǎi khráp"},"f":{"th":"คุณหิวไหมคะ","rom":"khun hǐu mǎi khá"}}]},{"h":"нравится","cells":[{"ru":"Мне нравится рис.","m":{"th":"ผมชอบข้าวครับ","rom":"phǒm chɔ̂ɔp khâao khráp"},"f":{"th":"ฉันชอบข้าวค่ะ","rom":"chǎn chɔ̂ɔp khâao khâ"}},{"ru":"Мне не нравится рис.","m":{"th":"ผมไม่ชอบข้าวครับ","rom":"phǒm mâi chɔ̂ɔp khâao khráp"},"f":{"th":"ฉันไม่ชอบข้าวค่ะ","rom":"chǎn mâi chɔ̂ɔp khâao khâ"}},{"ru":"Тебе нравится рис?","m":{"th":"คุณชอบข้าวไหมครับ","rom":"khun chɔ̂ɔp khâao mǎi khráp"},"f":{"th":"คุณชอบข้าวไหมคะ","rom":"khun chɔ̂ɔp khâao mǎi khá"}}]},{"h":"хочу","cells":[{"ru":"Я хочу есть.","m":{"th":"ผมอยากกินครับ","rom":"phǒm yàak gin khráp"},"f":{"th":"ฉันอยากกินค่ะ","rom":"chǎn yàak gin khâ"}},{"ru":"Я не хочу есть.","m":{"th":"ผมไม่อยากกินครับ","rom":"phǒm mâi yàak gin khráp"},"f":{"th":"ฉันไม่อยากกินค่ะ","rom":"chǎn mâi yàak gin khâ"}},{"ru":"Ты хочешь есть?","m":{"th":"คุณอยากกินไหมครับ","rom":"khun yàak gin mǎi khráp"},"f":{"th":"คุณอยากกินไหมคะ","rom":"khun yàak gin mǎi khá"}}]}]}],"drills":[{"ru":"Я учитель.","m":{"th":"ผมเป็นครูครับ","rom":"phǒm bpen khruu khráp"},"f":{"th":"ฉันเป็นครูค่ะ","rom":"chǎn bpen khruu khâ"}},{"ru":"Я не врач.","m":{"th":"ผมไม่ใช่หมอครับ","rom":"phǒm mâi-châi mɔ̌ɔ khráp"},"f":{"th":"ฉันไม่ใช่หมอค่ะ","rom":"chǎn mâi-châi mɔ̌ɔ khâ"}},{"ru":"Ты учитель?","m":{"th":"คุณเป็นครูไหมครับ","rom":"khun bpen khruu mǎi khráp"},"f":{"th":"คุณเป็นครูไหมคะ","rom":"khun bpen khruu mǎi khá"}},{"ru":"Я дома.","m":{"th":"ผมอยู่บ้านครับ","rom":"phǒm yùu bâan khráp"},"f":{"th":"ฉันอยู่บ้านค่ะ","rom":"chǎn yùu bâan khâ"}},{"ru":"Я голоден.","m":{"th":"ผมหิวครับ","rom":"phǒm hǐu khráp"},"f":{"th":"ฉันหิวค่ะ","rom":"chǎn hǐu khâ"}},{"ru":"Мне нравится рис.","m":{"th":"ผมชอบข้าวครับ","rom":"phǒm chɔ̂ɔp khâao khráp"},"f":{"th":"ฉันชอบข้าวค่ะ","rom":"chǎn chɔ̂ɔp khâao khâ"}},{"ru":"Я не хочу есть.","m":{"th":"ผมไม่อยากกินครับ","rom":"phǒm mâi yàak gin khráp"},"f":{"th":"ฉันไม่อยากกินค่ะ","rom":"chǎn mâi yàak gin khâ"}},{"ru":"Ты дома?","m":{"th":"คุณอยู่บ้านไหมครับ","rom":"khun yùu bâan mǎi khráp"},"f":{"th":"คุณอยู่บ้านไหมคะ","rom":"khun yùu bâan mǎi khá"}}],"self":"Скажите, кто вы по делу, где вы сейчас, голодны ли, что вам нравится и чего хотите. Потом через ไม่ใช่ скажите, что вы не врач."},{"id":4,"title":"Сказать, чьё это","goal":"Сказать «мой дом», «мамина книга», «это не моё» и спросить «это твоё?».","petrov":"Четвёртый шаг Петрова: притяжание. Хозяин стоит после вещи. Отдельное склонение не нужно.","formula":"Вещь, потом хозяин: บ้านผม. Между ними можно вставить ของ: หนังสือของผม. «Вот это» в начале фразы: นี่, падающий. Отрицание принадлежности: ไม่ใช่.","note":"แม่ผม значит «моя мама»: человек, потом чей он. Тот же порядок, что у вещи.","lead":{"ru":"Это мой дом.","m":{"th":"นี่บ้านผมครับ","rom":"nîi bâan phǒm khráp"},"f":{"th":"นี่บ้านฉันค่ะ","rom":"nîi bâan chǎn khâ"}},"words":[{"th":"นี่","rom":"nîi","ru":"вот это","how":"น это н. ี долгое и. ่ май-эк. Низкий класс плюс май-эк: падающий nîi. Этим начинают фразу, показывая на вещь: นี่บ้านผม. Не путайте с นี้ níi, высокий, которое стоит после слова."},{"th":"บ้าน","rom":"bâan","ru":"дом","how":"บ это b, средний класс. ้ май-тхо. า долгое а. น это н. Средний класс плюс май-тхо: падающий bâan."},{"th":"ของ","rom":"khɔ̌ɔng","ru":"вещь; также «кого» между вещью и хозяином","how":"ข это kh, высокий класс. อ долгое открытое о. ง это нг. Знака нет, живой слог: восходящий khɔ̌ɔng. Хозяина можно сказать и без него: บ้านผม уже «мой дом»."},{"th":"หนังสือ","rom":"nǎng-sʉ̌ʉ","ru":"книга","how":"หนัง: ห не читается, звук с н, ั краткое а, ง это нг. Высокий класс, живой слог: восходящий nǎng. สือ: ส высокий класс, ื долгое ʉ. Живой слог без знака: восходящий sʉ̌ʉ."},{"th":"แม่","rom":"mɛ̂ɛ","ru":"мама","how":"ม это м, низкий класс. แ долгое открытое э, пишется слева. ่ май-эк. Низкий класс плюс май-эк: падающий mɛ̂ɛ."},{"th":"พ่อ","rom":"phɔ̂ɔ","ru":"папа","how":"พ это ph с выдохом, низкий класс. ่ май-эк. อ долгое открытое о. Падающий phɔ̂ɔ."},{"th":"พี่","rom":"phîi","ru":"старший","how":"พ это ph. ี долгое и. ่ май-эк. Низкий класс плюс май-эк: падающий phîi."},{"th":"น้อง","rom":"nɔ́ɔng","ru":"младший","how":"น это н, низкий класс. ้ май-тхо. อ долгое о. ง это нг. Низкий класс плюс май-тхо: высокий nɔ́ɔng."},{"th":"เพื่อน","rom":"phʉ̂ʉan","ru":"друг","how":"พ это ph. เ, ื и อ дают гласный ʉa. ่ май-эк. น это н. Низкий класс плюс май-эк: падающий phʉ̂ʉan."},{"th":"ไม่ใช่","rom":"mâi-châi","ru":"это не так, я не тот","how":"ไม่ mâi, падающий, плюс ใช่. ใช่: ช это ch, ใ гласный ai, ่ май-эк. Низкий класс плюс май-эк: падающий châi. Вместе «не является». Так отрицают роль: ผมไม่ใช่หมอ «я не врач»."},{"th":"ผม","rom":"phǒm","ru":"я, мужской род","how":"Две буквы, гласной между ними на письме нет. ผ читается ph: п с выдохом. ม закрывает слог на м. Между ними краткое о. ผ высокого класса, слог живой, знака тона нет. Тон восходящий: phǒm."},{"th":"ฉัน","rom":"chǎn","ru":"я, женский род","how":"ฉ читается ch: ч с выдохом. ั это краткое а. น на конце н. Высокий класс, слог живой, знака нет. Тон восходящий: chǎn."}],"diagrams":[{"title":"Чей дом","slots":[{"role":"вот это","m":{"th":"นี่","rom":"nîi"},"f":{"th":"นี่","rom":"nîi"}},{"role":"вещь","m":{"th":"บ้าน","rom":"bâan"},"f":{"th":"บ้าน","rom":"bâan"}},{"role":"чей","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}}]}],"tables":[{"title":"Чьё","cols":["да","нет","вопрос"],"rows":[{"h":"дом","cells":[{"ru":"Это мой дом.","m":{"th":"นี่บ้านผมครับ","rom":"nîi bâan phǒm khráp"},"f":{"th":"นี่บ้านฉันค่ะ","rom":"nîi bâan chǎn khâ"}},{"ru":"Это не мой дом.","m":{"th":"นี่ไม่ใช่บ้านผมครับ","rom":"nîi mâi-châi bâan phǒm khráp"},"f":{"th":"นี่ไม่ใช่บ้านฉันค่ะ","rom":"nîi mâi-châi bâan chǎn khâ"}},{"ru":"Это твой дом?","m":{"th":"นี่บ้านคุณไหมครับ","rom":"nîi bâan khun mǎi khráp"},"f":{"th":"นี่บ้านคุณไหมคะ","rom":"nîi bâan khun mǎi khá"}}]},{"h":"книга","cells":[{"ru":"Это моя книга.","m":{"th":"นี่หนังสือของผมครับ","rom":"nîi nǎng-sʉ̌ʉ khɔ̌ɔng phǒm khráp"},"f":{"th":"นี่หนังสือของฉันค่ะ","rom":"nîi nǎng-sʉ̌ʉ khɔ̌ɔng chǎn khâ"}},{"ru":"Это не моя книга.","m":{"th":"นี่ไม่ใช่หนังสือผมครับ","rom":"nîi mâi-châi nǎng-sʉ̌ʉ phǒm khráp"},"f":{"th":"นี่ไม่ใช่หนังสือฉันค่ะ","rom":"nîi mâi-châi nǎng-sʉ̌ʉ chǎn khâ"}},{"ru":"Это твоя книга?","m":{"th":"นี่หนังสือคุณไหมครับ","rom":"nîi nǎng-sʉ̌ʉ khun mǎi khráp"},"f":{"th":"นี่หนังสือคุณไหมคะ","rom":"nîi nǎng-sʉ̌ʉ khun mǎi khá"}}]}]},{"title":"Мои люди, тот же порядок","cols":["фраза"],"rows":[{"h":"мама","cells":[{"ru":"Это моя мама.","m":{"th":"นี่แม่ผมครับ","rom":"nîi mɛ̂ɛ phǒm khráp"},"f":{"th":"นี่แม่ฉันค่ะ","rom":"nîi mɛ̂ɛ chǎn khâ"}}]},{"h":"папа","cells":[{"ru":"Это мой папа.","m":{"th":"นี่พ่อผมครับ","rom":"nîi phɔ̂ɔ phǒm khráp"},"f":{"th":"นี่พ่อฉันค่ะ","rom":"nîi phɔ̂ɔ chǎn khâ"}}]},{"h":"друг","cells":[{"ru":"Это мой друг.","m":{"th":"นี่เพื่อนผมครับ","rom":"nîi phʉ̂ʉan phǒm khráp"},"f":{"th":"นี่เพื่อนฉันค่ะ","rom":"nîi phʉ̂ʉan chǎn khâ"}}]},{"h":"старший","cells":[{"ru":"Это мой старший.","m":{"th":"นี่พี่ผมครับ","rom":"nîi phîi phǒm khráp"},"f":{"th":"นี่พี่ฉันค่ะ","rom":"nîi phîi chǎn khâ"}}]},{"h":"младший","cells":[{"ru":"Это мой младший.","m":{"th":"นี่น้องผมครับ","rom":"nîi nɔ́ɔng phǒm khráp"},"f":{"th":"นี่น้องฉันค่ะ","rom":"nîi nɔ́ɔng chǎn khâ"}}]},{"h":"ребёнок","cells":[{"ru":"Это мой ребёнок.","m":{"th":"นี่ลูกผมครับ","rom":"nîi lûuk phǒm khráp"},"f":{"th":"นี่ลูกฉันค่ะ","rom":"nîi lûuk chǎn khâ"}}]}]}],"drills":[{"ru":"Это мой дом.","m":{"th":"นี่บ้านผมครับ","rom":"nîi bâan phǒm khráp"},"f":{"th":"นี่บ้านฉันค่ะ","rom":"nîi bâan chǎn khâ"}},{"ru":"Это не мой дом.","m":{"th":"นี่ไม่ใช่บ้านผมครับ","rom":"nîi mâi-châi bâan phǒm khráp"},"f":{"th":"นี่ไม่ใช่บ้านฉันค่ะ","rom":"nîi mâi-châi bâan chǎn khâ"}},{"ru":"Это твой дом?","m":{"th":"นี่บ้านคุณไหมครับ","rom":"nîi bâan khun mǎi khráp"},"f":{"th":"นี่บ้านคุณไหมคะ","rom":"nîi bâan khun mǎi khá"}},{"ru":"Это моя книга.","m":{"th":"นี่หนังสือของผมครับ","rom":"nîi nǎng-sʉ̌ʉ khɔ̌ɔng phǒm khráp"},"f":{"th":"นี่หนังสือของฉันค่ะ","rom":"nîi nǎng-sʉ̌ʉ khɔ̌ɔng chǎn khâ"}},{"ru":"Это моя мама.","m":{"th":"นี่แม่ผมครับ","rom":"nîi mɛ̂ɛ phǒm khráp"},"f":{"th":"นี่แม่ฉันค่ะ","rom":"nîi mɛ̂ɛ chǎn khâ"}},{"ru":"Это мой друг.","m":{"th":"นี่เพื่อนผมครับ","rom":"nîi phʉ̂ʉan phǒm khráp"},"f":{"th":"นี่เพื่อนฉันค่ะ","rom":"nîi phʉ̂ʉan chǎn khâ"}}],"self":"Покажите три свои вещи и трёх своих людей. Сначала без ของ, потом ту же фразу с ของ. Спросите про одну чужую вещь."},{"id":5,"title":"Познакомиться и попросить повторить","goal":"Поздороваться, сказать, чем занимаетесь, попросить повторить и говорить медленнее.","petrov":"Пятый шаг Петрова: этикет и роль в живом разговоре. Фразы сразу закрываются вежливым словом и держат беседу, когда вы не расслышали.","formula":"Приветствие, потом ยินดีที่ได้รู้จัก. Имя стоит сразу после ชื่อ, без связки. Не расслышали: ไม่เข้าใจ, потом พูดอีกทีได้ไหม или พูดช้าๆได้ไหม.","note":"Имя подставляете своё. В ответ на вопрос о деле достаточно роли из третьего урока: ผมเป็นครู.","lead":{"ru":"Здравствуйте, очень приятно.","m":{"th":"สวัสดีครับ ยินดีที่ได้รู้จักครับ","rom":"sà-wàt-dii khráp yin-dii thîi dâai rúu-jàk khráp"},"f":{"th":"สวัสดีค่ะ ยินดีที่ได้รู้จักค่ะ","rom":"sà-wàt-dii khâ yin-dii thîi dâai rúu-jàk khâ"}},"words":[{"th":"สวัสดี","rom":"sà-wàt-dii","ru":"здравствуйте","how":"Три слога, все первые два низкие. ส даёт короткий слог sà и переводит следующий слог в высокий класс, поэтому วัส читается wàt низким, а не высоким. ดี: ด средний класс, ี долгое и, знака нет: средний dii. Конечное ส во втором слоге — глухое т."},{"th":"ชื่อ","rom":"chʉ̂ʉ","ru":"имя","how":"ช это ch, низкий класс. ื долгое ʉ. ่ май-эк. อ достраивает гласный. Падающий chʉ̂ʉ. Фраза «меня зовут» — это ผมชื่อ плюс имя, без связки."},{"th":"ยินดี","rom":"yin-dii","ru":"рад","how":"ยิน: ย это y, ิ краткое и, น это н. Низкий класс, живой слог: средний yin. ดี средний dii, как в สวัสดี."},{"th":"รู้จัก","rom":"rúu-jàk","ru":"быть знакомым","how":"รู้: ร низкий класс, ู долгое у, ้ май-тхо. Низкий класс плюс май-тхо: высокий rúu. จัก: จ средний класс, ั краткое а, ก глухое к. Короткий глухой слог среднего класса: низкий jàk."},{"th":"ขอโทษ","rom":"khɔ̌ɔ-thôot","ru":"извините","how":"ขอ: ข высокий класс, อ долгое о, живой слог без знака: восходящий khɔ̌ɔ. โทษ: ท это th, โ долгое о, ษ на конце глухое т. Долгий глухой слог низкого класса: падающий thôot."},{"th":"ขอบคุณ","rom":"khɔ̀ɔp-khun","ru":"спасибо","how":"ขอบ: ข высокий класс, долгое о, บ глухое п. Долгий глухой слог высокого класса без знака: низкий khɔ̀ɔp. Второй слог это คุณ khun, средний."},{"th":"เข้าใจ","rom":"khâo-jai","ru":"понимать","how":"เข้า: ข высокий класс, เ и า дают ao, ้ май-тхо. Высокий класс плюс май-тхо: падающий khâo. ใจ: จ средний класс, ใ гласный ai, знака нет: средний jai. ไม่เข้าใจ «не понимаю»."},{"th":"พูด","rom":"phûut","ru":"говорить","how":"พ это ph, низкий класс. ู долгое у. ด на конце глухое т. Знака тона нет. Долгий глухой слог низкого класса: падающий phûut."},{"th":"อีก","rom":"ìik","ru":"ещё","how":"อ задаёт средний класс. ี долгое и. ก на конце глухое к. Знака нет. Долгий глухой слог среднего класса: низкий ìik."},{"th":"ที","rom":"thii","ru":"раз, в อีกที","how":"ท это th. ี долгое и. Низкий класс, живой слог, знака нет: средний thii. อีกที «ещё раз»."},{"th":"ช้า","rom":"cháa","ru":"медленно","how":"ช это ch, низкий класс. ้ май-тхо. า долгое а. Низкий класс плюс май-тхо: высокий cháa. Повтор ช้าๆ значит «медленно, потихоньку»: cháa-cháa."},{"th":"ทำ","rom":"tham","ru":"делать","how":"ท это th. ำ это am. Низкий класс, живой слог, знака нет: средний tham. คุณทำอะไร «вы делаете что», так спрашивают и занятие."},{"th":"งาน","rom":"ngaan","ru":"работа, дело","how":"ง это ng, может начинать слово. า долгое а. น это н. Низкий класс, живой слог: средний ngaan. ทำงาน tham-ngaan «работать»."},{"th":"ได้","rom":"dâai","ru":"получилось; в ไม่ได้ меняет смысл от места","how":"ไ слева, гласный ai. ด это d. ้ это май-тхо. Средний класс плюс май-тхо дают падающий тон: dâai. Перед действием ไม่ได้ значит «не сделал». После действия ได้ значит «могу», ไม่ได้ значит «не могу»."},{"th":"ไหม","rom":"mǎi","ru":"ли, вопрос да или нет","how":"ห не читается: она только переводит слог в высокий класс. Звук начинается с м, гласный тот же ai, что в ไม่. Знака тона нет. Высокий класс и живой слог дают восходящий тон: mǎi. Стоит в конце фразы, перед ครับ khráp или คะ khá. С падающим ไม่ это разные слова."},{"th":"เป็น","rom":"bpen","ru":"являться кем-то, роль","how":"ป это bp без выдоха. เ и ็ дают краткое э. น это н. Средний класс, живой слог: средний bpen. Этим говорят профессию и роль. «Я не врач» так не отрицается."},{"th":"ครู","rom":"khruu","ru":"учитель","how":"ค это kh. ร в речи слабое. ู долгое у. Низкий класс, живой слог, знака нет: средний khruu."}],"diagrams":[{"title":"Попросить ещё раз","slots":[{"role":"действие","m":{"th":"พูด","rom":"phûut"},"f":{"th":"พูด","rom":"phûut"}},{"role":"ещё раз","m":{"th":"อีกที","rom":"ìik-thii"},"f":{"th":"อีกที","rom":"ìik-thii"}},{"role":"можно","m":{"th":"ได้ไหม","rom":"dâai mǎi"},"f":{"th":"ได้ไหม","rom":"dâai mǎi"}}]}],"tables":[{"title":"Знакомство","cols":["да","нет","вопрос"],"rows":[{"h":"понимаю","cells":[{"ru":"Я понимаю.","m":{"th":"เข้าใจครับ","rom":"khâo-jai khráp"},"f":{"th":"เข้าใจค่ะ","rom":"khâo-jai khâ"}},{"ru":"Я не понимаю.","m":{"th":"ผมไม่เข้าใจครับ","rom":"phǒm mâi khâo-jai khráp"},"f":{"th":"ฉันไม่เข้าใจค่ะ","rom":"chǎn mâi khâo-jai khâ"}},{"ru":"Ты понимаешь?","m":{"th":"คุณเข้าใจไหมครับ","rom":"khun khâo-jai mǎi khráp"},"f":{"th":"คุณเข้าใจไหมคะ","rom":"khun khâo-jai mǎi khá"}}]},{"h":"дело","cells":[{"ru":"Я учитель.","m":{"th":"ผมเป็นครูครับ","rom":"phǒm bpen khruu khráp"},"f":{"th":"ฉันเป็นครูค่ะ","rom":"chǎn bpen khruu khâ"}},{"ru":"Я не учитель.","m":{"th":"ผมไม่ใช่ครูครับ","rom":"phǒm mâi-châi khruu khráp"},"f":{"th":"ฉันไม่ใช่ครูค่ะ","rom":"chǎn mâi-châi khruu khâ"}},{"ru":"Чем ты занимаешься?","m":{"th":"คุณทำอะไรครับ","rom":"khun tham à-rai khráp"},"f":{"th":"คุณทำอะไรคะ","rom":"khun tham à-rai khá"}}]}]}],"drills":[{"ru":"Здравствуйте.","m":{"th":"สวัสดีครับ","rom":"sà-wàt-dii khráp"},"f":{"th":"สวัสดีค่ะ","rom":"sà-wàt-dii khâ"}},{"ru":"Очень приятно.","m":{"th":"ยินดีที่ได้รู้จักครับ","rom":"yin-dii thîi dâai rúu-jàk khráp"},"f":{"th":"ยินดีที่ได้รู้จักค่ะ","rom":"yin-dii thîi dâai rúu-jàk khâ"}},{"ru":"Как вас зовут?","m":{"th":"คุณชื่ออะไรครับ","rom":"khun chʉ̂ʉ à-rai khráp"},"f":{"th":"คุณชื่ออะไรคะ","rom":"khun chʉ̂ʉ à-rai khá"}},{"ru":"Я не понимаю.","m":{"th":"ผมไม่เข้าใจครับ","rom":"phǒm mâi khâo-jai khráp"},"f":{"th":"ฉันไม่เข้าใจค่ะ","rom":"chǎn mâi khâo-jai khâ"}},{"ru":"Скажите ещё раз, пожалуйста?","m":{"th":"พูดอีกทีได้ไหมครับ","rom":"phûut ìik-thii dâai mǎi khráp"},"f":{"th":"พูดอีกทีได้ไหมคะ","rom":"phûut ìik-thii dâai mǎi khá"}},{"ru":"Говорите медленно, пожалуйста?","m":{"th":"พูดช้าๆได้ไหมครับ","rom":"phûut cháa-cháa dâai mǎi khráp"},"f":{"th":"พูดช้าๆได้ไหมคะ","rom":"phûut cháa-cháa dâai mǎi khá"}},{"ru":"Спасибо.","m":{"th":"ขอบคุณครับ","rom":"khɔ̀ɔp-khun khráp"},"f":{"th":"ขอบคุณค่ะ","rom":"khɔ̀ɔp-khun khâ"}},{"ru":"Извините.","m":{"th":"ขอโทษครับ","rom":"khɔ̌ɔ-thôot khráp"},"f":{"th":"ขอโทษค่ะ","rom":"khɔ̌ɔ-thôot khâ"}},{"ru":"Чем ты занимаешься?","m":{"th":"คุณทำอะไรครับ","rom":"khun tham à-rai khráp"},"f":{"th":"คุณทำอะไรคะ","rom":"khun tham à-rai khá"}}],"self":"Поздоровайтесь, скажите своё имя после ชื่อ и кем вы работаете. Потом три просьбы: не понял, ещё раз, медленнее. Закройте каждую фразу своим вежливым словом."},{"id":6,"title":"Сравнить и выбрать","goal":"Сказать, что вот это больше, дешевле, вкуснее и какое самое. Показать «это» и «то».","petrov":"Шестой шаг Петрова: сравнение и «этот / тот». Признак сам работает как сказуемое.","formula":"Вещь, потом признак: อันนี้ใหญ่. Сравнение: признак + กว่า + второе. Самый: признак + ที่สุด. Связку เป็น перед большим, дешёвым и вкусным не ставьте.","note":"อันนี้ высокий на втором слоге: an-níi. อันนั้น тоже: an-nán. Начало фразы «вот это» из четвёртого урока, นี่, другое слово и другой тон.","lead":{"ru":"Вот это дешевле, чем то.","m":{"th":"อันนี้ถูกกว่าอันนั้นครับ","rom":"an-níi thùuk gwàa an-nán khráp"},"f":{"th":"อันนี้ถูกกว่าอันนั้นค่ะ","rom":"an-níi thùuk gwàa an-nán khâ"}},"words":[{"th":"อัน","rom":"an","ru":"штука, для вещи без своего счётного слова","how":"อ средний класс. ั краткое а. น это н. Живой слог без знака: средний an. อันนี้ «вот эта штука», อันนั้น «вон та»."},{"th":"นี้","rom":"níi","ru":"этот, после слова","how":"น это н, ี долгое и, ้ май-тхо. Низкий класс плюс май-тхо: высокий níi. Стоит после вещи: อันนี้, วันนี้, พรุ่งนี้. Отдельное «вот это» в начале фразы пишется นี่ и падает."},{"th":"นั้น","rom":"nán","ru":"тот","how":"น низкий класс. ั краткое а. ้ май-тхо. น на конце. Низкий класс плюс май-тхо: высокий nán. В อันนั้น первый слог средний, второй высокий."},{"th":"ใหญ่","rom":"yài","ru":"большой","how":"ห не читается. ญ даёт звук y. ใ гласный ai. ่ май-эк. Высокий класс плюс май-эк: низкий yài. Признак сам по себе сказуемое: อันนี้ใหญ่ «это большое». Связку не ставьте."},{"th":"เล็ก","rom":"lék","ru":"маленький","how":"ล низкий класс. เ и ็ краткое э. ก глухое к. Короткий глухой слог низкого класса без знака: высокий lék."},{"th":"ถูก","rom":"thùuk","ru":"дешёвый; также «верно»","how":"ถ это th, высокий класс. ู долгое у. ก глухое к. Знака тона нет. Долгий глухой слог высокого класса: низкий thùuk."},{"th":"แพง","rom":"phɛɛng","ru":"дорогой","how":"พ это ph, низкий класс. แ долгое открытое э. ง это нг. Знака нет, живой слог: средний phɛɛng."},{"th":"กว่า","rom":"gwàa","ru":"чем, в сравнении","how":"ก это g. ว это w внутри слога. ่ май-эк. า долгое а. Средний класс плюс май-эк: низкий gwàa. Порядок: признак, потом กว่า, потом с чем сравниваете."},{"th":"ที่สุด","rom":"thîi-sùt","ru":"самый","how":"ที่ thîi падает. สุด: ส высокий класс, ุ краткое у, ด глухое т. Короткий глухой слог высокого класса: низкий sùt. Стоит после признака: ใหญ่ที่สุด «самый большой»."},{"th":"อร่อย","rom":"à-rɔ̀i","ru":"вкусно","how":"Читайте целиком, оба слога низкие. Первая อ даёт краткое а низким тоном: средний класс, короткий слог. Дальше ร, ่ и อย слышатся rɔ̀i, тоже низкий. Тон второго слога лучше запомнить вместе со словом, не собирать заново с видимого знака."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."}],"diagrams":[{"title":"Сравнение","slots":[{"role":"это","m":{"th":"อันนี้","rom":"an-níi"},"f":{"th":"อันนี้","rom":"an-níi"}},{"role":"признак","m":{"th":"ถูก","rom":"thùuk"},"f":{"th":"ถูก","rom":"thùuk"}},{"role":"чем","m":{"th":"กว่า","rom":"gwàa"},"f":{"th":"กว่า","rom":"gwàa"}},{"role":"то","m":{"th":"อันนั้น","rom":"an-nán"},"f":{"th":"อันนั้น","rom":"an-nán"}}]}],"tables":[{"title":"Выбрать","cols":["да","нет","вопрос"],"rows":[{"h":"размер","cells":[{"ru":"Вот это большое.","m":{"th":"อันนี้ใหญ่ครับ","rom":"an-níi yài khráp"},"f":{"th":"อันนี้ใหญ่ค่ะ","rom":"an-níi yài khâ"}},{"ru":"Вот это не большое.","m":{"th":"อันนี้ไม่ใหญ่ครับ","rom":"an-níi mâi yài khráp"},"f":{"th":"อันนี้ไม่ใหญ่ค่ะ","rom":"an-níi mâi yài khâ"}},{"ru":"Вот это большое?","m":{"th":"อันนี้ใหญ่ไหมครับ","rom":"an-níi yài mǎi khráp"},"f":{"th":"อันนี้ใหญ่ไหมคะ","rom":"an-níi yài mǎi khá"}}]},{"h":"цена","cells":[{"ru":"Вот это дешевле, чем то.","m":{"th":"อันนี้ถูกกว่าอันนั้นครับ","rom":"an-níi thùuk gwàa an-nán khráp"},"f":{"th":"อันนี้ถูกกว่าอันนั้นค่ะ","rom":"an-níi thùuk gwàa an-nán khâ"}},{"ru":"Вот это дороже, чем то.","m":{"th":"อันนี้แพงกว่าอันนั้นครับ","rom":"an-níi phɛɛng gwàa an-nán khráp"},"f":{"th":"อันนี้แพงกว่าอันนั้นค่ะ","rom":"an-níi phɛɛng gwàa an-nán khâ"}},{"ru":"Вот это дешевле, чем то?","m":{"th":"อันนี้ถูกกว่าอันนั้นไหมครับ","rom":"an-níi thùuk gwàa an-nán mǎi khráp"},"f":{"th":"อันนี้ถูกกว่าอันนั้นไหมคะ","rom":"an-níi thùuk gwàa an-nán mǎi khá"}}]},{"h":"вкус","cells":[{"ru":"Вот это самое вкусное.","m":{"th":"อันนี้อร่อยที่สุดครับ","rom":"an-níi à-rɔ̀i thîi-sùt khráp"},"f":{"th":"อันนี้อร่อยที่สุดค่ะ","rom":"an-níi à-rɔ̀i thîi-sùt khâ"}},{"ru":"Вот это не вкусное.","m":{"th":"อันนี้ไม่อร่อยครับ","rom":"an-níi mâi à-rɔ̀i khráp"},"f":{"th":"อันนี้ไม่อร่อยค่ะ","rom":"an-níi mâi à-rɔ̀i khâ"}},{"ru":"Вот это вкусное?","m":{"th":"อันนี้อร่อยไหมครับ","rom":"an-níi à-rɔ̀i mǎi khráp"},"f":{"th":"อันนี้อร่อยไหมคะ","rom":"an-níi à-rɔ̀i mǎi khá"}}]}]}],"drills":[{"ru":"Вот это большое.","m":{"th":"อันนี้ใหญ่ครับ","rom":"an-níi yài khráp"},"f":{"th":"อันนี้ใหญ่ค่ะ","rom":"an-níi yài khâ"}},{"ru":"Вот это маленькое.","m":{"th":"อันนี้เล็กครับ","rom":"an-níi lék khráp"},"f":{"th":"อันนี้เล็กค่ะ","rom":"an-níi lék khâ"}},{"ru":"Вот это дешевле, чем то.","m":{"th":"อันนี้ถูกกว่าอันนั้นครับ","rom":"an-níi thùuk gwàa an-nán khráp"},"f":{"th":"อันนี้ถูกกว่าอันนั้นค่ะ","rom":"an-níi thùuk gwàa an-nán khâ"}},{"ru":"Вот это дороже, чем то.","m":{"th":"อันนี้แพงกว่าอันนั้นครับ","rom":"an-níi phɛɛng gwàa an-nán khráp"},"f":{"th":"อันนี้แพงกว่าอันนั้นค่ะ","rom":"an-níi phɛɛng gwàa an-nán khâ"}},{"ru":"Вот это самое вкусное.","m":{"th":"อันนี้อร่อยที่สุดครับ","rom":"an-níi à-rɔ̀i thîi-sùt khráp"},"f":{"th":"อันนี้อร่อยที่สุดค่ะ","rom":"an-níi à-rɔ̀i thîi-sùt khâ"}},{"ru":"Вот это большое?","m":{"th":"อันนี้ใหญ่ไหมครับ","rom":"an-níi yài mǎi khráp"},"f":{"th":"อันนี้ใหญ่ไหมคะ","rom":"an-níi yài mǎi khá"}},{"ru":"Вот это не вкусное.","m":{"th":"อันนี้ไม่อร่อยครับ","rom":"an-níi mâi à-rɔ̀i khráp"},"f":{"th":"อันนี้ไม่อร่อยค่ะ","rom":"an-níi mâi à-rɔ̀i khâ"}}],"self":"Положите рядом две вещи. Скажите, какая больше, какая дешевле и какая вам нравится больше. Потом скажите, какая самая вкусная из того, что вы едите."},{"id":7,"title":"Сказать, сколько и почём","goal":"Назвать число вещей и цену. Спросить «сколько?» и «почём?».","petrov":"Седьмой шаг Петрова: количество. Число не стоит перед вещью, как в русском. Вещь, потом число, потом счётное слово.","formula":"น้ำสองแก้ว: вода, два, стакан. คนสามคน: люди, три, человека. Цена: อันนี้ห้าสิบบาท. Вопрос количества: กี่ перед тем же счётным словом. 11 это สิบเอ็ด, не สิบหนึ่ง. 20 это ยี่สิบ, не สองสิบ.","note":"Счётное слово обязательно, даже если по-русски его нет. Книга: เล่ม. Тарелка риса: จาน. Стакан: แก้ว. Человек: คน. Баты считаются без отдельного «штук»: ห้าสิบบาท.","lead":{"ru":"Два стакана воды.","m":{"th":"น้ำสองแก้วครับ","rom":"náam sɔ̌ɔng gâeo khráp"},"f":{"th":"น้ำสองแก้วค่ะ","rom":"náam sɔ̌ɔng gâeo khâ"}},"words":[{"th":"หนึ่ง","rom":"nʉ̀ng","ru":"один","how":"ห не читается и делает класс высоким. น это н. ึ краткое ʉ. ่ май-эк. ง это нг. Высокий класс плюс май-эк: низкий nʉ̀ng. В числе 11 будет не это слово, а เอ็ด."},{"th":"สอง","rom":"sɔ̌ɔng","ru":"два","how":"ส высокий класс. อ долгое открытое о. ง это нг. Живой слог без знака: восходящий sɔ̌ɔng. 20 говорят ยี่สิบ, не สองสิบ."},{"th":"สาม","rom":"sǎam","ru":"три","how":"ส высокий класс. า долгое а. ม это м. Живой слог без знака: восходящий sǎam."},{"th":"สี่","rom":"sìi","ru":"четыре","how":"ส высокий класс. ี долгое и. ่ май-эк. Высокий класс плюс май-эк: низкий sìi."},{"th":"ห้า","rom":"hâa","ru":"пять","how":"ห это h, высокий класс. ้ май-тхо. า долгое а. Высокий класс плюс май-тхо: падающий hâa."},{"th":"หก","rom":"hòk","ru":"шесть","how":"ห высокий класс. Гласной на письме нет, слышится краткое о. ก глухое к. Короткий глухой слог высокого класса: низкий hòk."},{"th":"เจ็ด","rom":"jèt","ru":"семь","how":"จ это j, средний класс. เ и ็ краткое э. ด глухое т. Короткий глухой слог среднего класса: низкий jèt."},{"th":"แปด","rom":"bpɛ̀ɛt","ru":"восемь","how":"ป это bp без выдоха. แ долгое открытое э. ด глухое т. Знака нет. Долгий глухой слог среднего класса: низкий bpɛ̀ɛt."},{"th":"เก้า","rom":"gâao","ru":"девять","how":"ก это g, средний класс. เ и า дают ao. ้ май-тхо. Средний класс плюс май-тхо: падающий gâao."},{"th":"สิบ","rom":"sìp","ru":"десять","how":"ส высокий класс. ิ краткое и. บ глухое п. Короткий глухой слог высокого класса: низкий sìp. 50 это ห้าสิบ: пять и десять, не отдельное слово."},{"th":"สิบเอ็ด","rom":"sìp-èt","ru":"одиннадцать","how":"สิบ sìp плюс เอ็ด, не หนึ่ง. เอ็ด: อ средний класс, краткое э, ด глухое т. Короткий глухой слог: низкий èt."},{"th":"ยี่","rom":"yîi","ru":"два, только в числе 20","how":"ย это y, низкий класс. ี долгое и. ่ май-эк. Низкий класс плюс май-эк: падающий yîi. ยี่สิบ «двадцать»."},{"th":"ร้อย","rom":"rɔ́ɔi","ru":"сто","how":"ร низкий класс. ้ май-тхо. О долгое открытое о, ย закрывает слог. Низкий класс плюс май-тхо: высокий rɔ́ɔi."},{"th":"น้ำ","rom":"náam","ru":"вода","how":"น низкий класс. ้ май-тхо. ำ это долгое ам. Низкий класс плюс май-тхо: высокий náam."},{"th":"แก้ว","rom":"gâeo","ru":"стакан, счётное слово для стаканов","how":"ก средний класс. แ и ว дают гласный aeo. ้ май-тхо. Средний класс плюс май-тхо: падающий gâeo. Счёт: น้ำสองแก้ว «воды два стакана»."},{"th":"บาท","rom":"bàat","ru":"бат","how":"บ средний класс. า долгое а. ท на конце глухое т, не th. Знака нет. Долгий глухой слог среднего класса: низкий bàat."},{"th":"กี่","rom":"gìi","ru":"сколько","how":"ก это g, средний класс. ี долгое и. ่ май-эк. Средний класс плюс май-эк: низкий gìi. Стоит перед счётным словом: กี่แก้ว, กี่บาท, กี่คน."},{"th":"คน","rom":"khon","ru":"человек; счётное слово для людей","how":"ค это kh. Гласной на письме нет, слышится краткое о. น это н. Низкий класс, живой слог: средний khon. คนสามคน «людей три человека»."},{"th":"เล่ม","rom":"lêm","ru":"счётное слово для книг","how":"ล низкий класс. เ гласный э, здесь долгий. ่ май-эк. ม это м. Низкий класс плюс май-эк: падающий lêm. หนังสือหนึ่งเล่ม «книга один экземпляр»."},{"th":"จาน","rom":"jaan","ru":"тарелка","how":"จ средний класс. า долгое а. น это н. Живой слог без знака: средний jaan. ข้าวหนึ่งจาน «риса одна тарелка»."},{"th":"ข้าว","rom":"khâao","ru":"рис, еда","how":"ข это kh, высокий класс. ้ май-тхо. า долгое а, ว достраивает гласный ao. Высокий класс плюс май-тхо: падающий khâao."},{"th":"หนังสือ","rom":"nǎng-sʉ̌ʉ","ru":"книга","how":"หนัง: ห не читается, звук с н, ั краткое а, ง это нг. Высокий класс, живой слог: восходящий nǎng. สือ: ส высокий класс, ื долгое ʉ. Живой слог без знака: восходящий sʉ̌ʉ."},{"th":"อัน","rom":"an","ru":"штука, для вещи без своего счётного слова","how":"อ средний класс. ั краткое а. น это н. Живой слог без знака: средний an. อันนี้ «вот эта штука», อันนั้น «вон та»."},{"th":"นี้","rom":"níi","ru":"этот, после слова","how":"น это н, ี долгое и, ้ май-тхо. Низкий класс плюс май-тхо: высокий níi. Стоит после вещи: อันนี้, วันนี้, พรุ่งนี้. Отдельное «вот это» в начале фразы пишется นี่ и падает."},{"th":"ไม่ใช่","rom":"mâi-châi","ru":"это не так, я не тот","how":"ไม่ mâi, падающий, плюс ใช่. ใช่: ช это ch, ใ гласный ai, ่ май-эк. Низкий класс плюс май-эк: падающий châi. Вместе «не является». Так отрицают роль: ผมไม่ใช่หมอ «я не врач»."}],"diagrams":[{"title":"Два стакана","slots":[{"role":"вещь","m":{"th":"น้ำ","rom":"náam"},"f":{"th":"น้ำ","rom":"náam"}},{"role":"число","m":{"th":"สอง","rom":"sɔ̌ɔng"},"f":{"th":"สอง","rom":"sɔ̌ɔng"}},{"role":"счётное","m":{"th":"แก้ว","rom":"gâeo"},"f":{"th":"แก้ว","rom":"gâeo"}}]}],"tables":[{"title":"Цена","cols":["да","нет","вопрос"],"rows":[{"h":"пятьдесят","cells":[{"ru":"Вот это пятьдесят бат.","m":{"th":"อันนี้ห้าสิบบาทครับ","rom":"an-níi hâa-sìp bàat khráp"},"f":{"th":"อันนี้ห้าสิบบาทค่ะ","rom":"an-níi hâa-sìp bàat khâ"}},{"ru":"Вот это не пятьдесят бат.","m":{"th":"อันนี้ไม่ใช่ห้าสิบบาทครับ","rom":"an-níi mâi-châi hâa-sìp bàat khráp"},"f":{"th":"อันนี้ไม่ใช่ห้าสิบบาทค่ะ","rom":"an-níi mâi-châi hâa-sìp bàat khâ"}},{"ru":"Сколько это стоит?","m":{"th":"อันนี้กี่บาทครับ","rom":"an-níi gìi bàat khráp"},"f":{"th":"อันนี้กี่บาทคะ","rom":"an-níi gìi bàat khá"}}]}]},{"title":"Сколько вещей","cols":["сказать","спросить"],"rows":[{"h":"вода","cells":[{"ru":"Два стакана воды.","m":{"th":"น้ำสองแก้วครับ","rom":"náam sɔ̌ɔng gâeo khráp"},"f":{"th":"น้ำสองแก้วค่ะ","rom":"náam sɔ̌ɔng gâeo khâ"}},{"ru":"Сколько стаканов воды?","m":{"th":"น้ำกี่แก้วครับ","rom":"náam gìi gâeo khráp"},"f":{"th":"น้ำกี่แก้วคะ","rom":"náam gìi gâeo khá"}}]},{"h":"люди","cells":[{"ru":"Три человека.","m":{"th":"คนสามคนครับ","rom":"khon sǎam khon khráp"},"f":{"th":"คนสามคนค่ะ","rom":"khon sǎam khon khâ"}},{"ru":"Сколько человек?","m":{"th":"คนกี่คนครับ","rom":"khon gìi khon khráp"},"f":{"th":"คนกี่คนคะ","rom":"khon gìi khon khá"}}]},{"h":"книга","cells":[{"ru":"Одна книга.","m":{"th":"หนังสือหนึ่งเล่มครับ","rom":"nǎng-sʉ̌ʉ nʉ̀ng lêm khráp"},"f":{"th":"หนังสือหนึ่งเล่มค่ะ","rom":"nǎng-sʉ̌ʉ nʉ̀ng lêm khâ"}},{"ru":"Сколько книг?","m":{"th":"หนังสือกี่เล่มครับ","rom":"nǎng-sʉ̌ʉ gìi lêm khráp"},"f":{"th":"หนังสือกี่เล่มคะ","rom":"nǎng-sʉ̌ʉ gìi lêm khá"}}]},{"h":"рис","cells":[{"ru":"Одна тарелка риса.","m":{"th":"ข้าวหนึ่งจานครับ","rom":"khâao nʉ̀ng jaan khráp"},"f":{"th":"ข้าวหนึ่งจานค่ะ","rom":"khâao nʉ̀ng jaan khâ"}},{"ru":"Сколько тарелок риса?","m":{"th":"ข้าวกี่จานครับ","rom":"khâao gìi jaan khráp"},"f":{"th":"ข้าวกี่จานคะ","rom":"khâao gìi jaan khá"}}]}]},{"title":"Две ловушки счёта","cols":["фраза"],"rows":[{"h":"11","cells":[{"ru":"Одиннадцать бат.","m":{"th":"สิบเอ็ดบาทครับ","rom":"sìp-èt bàat khráp"},"f":{"th":"สิบเอ็ดบาทค่ะ","rom":"sìp-èt bàat khâ"}}]},{"h":"20","cells":[{"ru":"Двадцать бат.","m":{"th":"ยี่สิบบาทครับ","rom":"yîi-sìp bàat khráp"},"f":{"th":"ยี่สิบบาทค่ะ","rom":"yîi-sìp bàat khâ"}}]},{"h":"100","cells":[{"ru":"Сто бат.","m":{"th":"ร้อยบาทครับ","rom":"rɔ́ɔi bàat khráp"},"f":{"th":"ร้อยบาทค่ะ","rom":"rɔ́ɔi bàat khâ"}}]}]}],"drills":[{"ru":"Два стакана воды.","m":{"th":"น้ำสองแก้วครับ","rom":"náam sɔ̌ɔng gâeo khráp"},"f":{"th":"น้ำสองแก้วค่ะ","rom":"náam sɔ̌ɔng gâeo khâ"}},{"ru":"Сколько это стоит?","m":{"th":"อันนี้กี่บาทครับ","rom":"an-níi gìi bàat khráp"},"f":{"th":"อันนี้กี่บาทคะ","rom":"an-níi gìi bàat khá"}},{"ru":"Вот это пятьдесят бат.","m":{"th":"อันนี้ห้าสิบบาทครับ","rom":"an-níi hâa-sìp bàat khráp"},"f":{"th":"อันนี้ห้าสิบบาทค่ะ","rom":"an-níi hâa-sìp bàat khâ"}},{"ru":"Три человека.","m":{"th":"คนสามคนครับ","rom":"khon sǎam khon khráp"},"f":{"th":"คนสามคนค่ะ","rom":"khon sǎam khon khâ"}},{"ru":"Одна книга.","m":{"th":"หนังสือหนึ่งเล่มครับ","rom":"nǎng-sʉ̌ʉ nʉ̀ng lêm khráp"},"f":{"th":"หนังสือหนึ่งเล่มค่ะ","rom":"nǎng-sʉ̌ʉ nʉ̀ng lêm khâ"}},{"ru":"Одиннадцать бат.","m":{"th":"สิบเอ็ดบาทครับ","rom":"sìp-èt bàat khráp"},"f":{"th":"สิบเอ็ดบาทค่ะ","rom":"sìp-èt bàat khâ"}},{"ru":"Двадцать бат.","m":{"th":"ยี่สิบบาทครับ","rom":"yîi-sìp bàat khráp"},"f":{"th":"ยี่สิบบาทค่ะ","rom":"yîi-sìp bàat khâ"}},{"ru":"Сколько стаканов воды?","m":{"th":"น้ำกี่แก้วครับ","rom":"náam gìi gâeo khráp"},"f":{"th":"น้ำกี่แก้วคะ","rom":"náam gìi gâeo khá"}}],"self":"Назовите цену трёх вещей вокруг себя и количество двух из них. Спросите вслух «сколько стоит» про одну. 11 и 20 скажите отдельными фразами, чтобы не сбиться на русский порядок."},{"id":8,"title":"Сказать, во сколько и в какой день","goal":"Назвать час и день. Поставить это время перед тем же глаголом «иду», не меняя глагол.","petrov":"Восьмой шаг Петрова: время. Час и день — рамка в начале. Глагол остаётся ไป.","formula":"Сначала когда, потом кто, потом действие. แปดโมงเช้าผมไป. Отрицание плана: ไม่ไป. Отрицание того, что уже не случилось: ไม่ได้ไป. День: วันนี้วันจันทร์.","note":"Тайские часы не делятся на ровные «час плюс число». Учите готовые фразы: 7–11 утра через โมงเช้า, полдень เที่ยง, 13:00 บ่ายโมง, 14:00 บ่ายสองโมง, 16–18 через โมงเย็น, 19:00 หนึ่งทุ่ม, 20:00 สองทุ่ม, час ночи ตีหนึ่ง.","lead":{"ru":"Сейчас восемь утра.","m":{"th":"ตอนนี้แปดโมงเช้าครับ","rom":"dtɔɔn-níi bpɛ̀ɛt moong cháao khráp"},"f":{"th":"ตอนนี้แปดโมงเช้าค่ะ","rom":"dtɔɔn-níi bpɛ̀ɛt moong cháao khâ"}},"words":[{"th":"ตอนนี้","rom":"dtɔɔn-níi","ru":"сейчас","how":"ตอน dtɔɔn средний и นี้ níi высокий. Время-рамка, глагол от него не меняется."},{"th":"ตอน","rom":"dtɔɔn","ru":"момент, в ตอนนี้","how":"ต это dt. อ долгое открытое о. น это н. Средний класс, живой слог: средний dtɔɔn. ตอนนี้ «сейчас»: второй слог высокий níi."},{"th":"วันนี้","rom":"wan-níi","ru":"сегодня","how":"วัน wan, средний, плюс นี้ níi, высокий. Второй слог с май-тхо, не падающий."},{"th":"วัน","rom":"wan","ru":"день","how":"ว это w, низкий класс. ั краткое а. น это н. Живой слог без знака: средний wan. Перед названием дня: วันจันทร์."},{"th":"โมง","rom":"moong","ru":"час в дневном счёте","how":"ม низкий класс. โ долгое о. ง это нг. Живой слог без знака: средний moong. Утро: число и โมงเช้า. Не всякий час называется так, смотрите готовые фразы урока."},{"th":"เช้า","rom":"cháao","ru":"утро","how":"ช низкий класс. เ и า дают ao. ้ май-тхо. Низкий класс плюс май-тхо: высокий cháao."},{"th":"เที่ยง","rom":"thìang","ru":"полдень","how":"ท это th, низкий класс. เ, ี и ย дают гласный ia. ่ май-эк. ง это нг. Низкий класс плюс май-эк: падающий thìang. Один это слово значит 12:00."},{"th":"บ่าย","rom":"bàai","ru":"после полудня","how":"บ средний класс. ่ май-эк. า долгое а. ย закрывает слог. Средний класс плюс май-эк: низкий bàai. บ่ายโมง это 13:00, บ่ายสองโมง это 14:00."},{"th":"เย็น","rom":"yen","ru":"вечер около 16–18; также «прохладный»","how":"ย низкий класс. เ и ็ краткое э. น это н. Живой слог без знака: средний yen. สี่โมงเย็น 16:00, ห้าโมงเย็น 17:00, หกโมงเย็น 18:00."},{"th":"ทุ่ม","rom":"thûm","ru":"час вечернего счёта","how":"ท это th, низкий класс. ุ краткое у. ่ май-эк. ม это м. Низкий класс плюс май-эк: падающий thûm. หนึ่งทุ่ม 19:00, สองทุ่ม 20:00."},{"th":"ตี","rom":"dtii","ru":"час после полуночи","how":"ต читается dt: т без выдоха. ี долгое и. Средний класс, живой слог, знака нет: средний dtii. ตีหนึ่ง это 1:00 ночи."},{"th":"จันทร์","rom":"jan","ru":"понедельник","how":"Слышится один средний слог jan. จ это j, ั краткое а, น это н. Буквы ทร์ на конце не читаются. Не произносите их."},{"th":"อังคาร","rom":"ang-khaan","ru":"вторник","how":"อัง: อ средний класс, краткое а, ง это нг, тон средний ang. คาร: ค это kh, า долгое а, ร на конце слабое. Низкий класс, живой слог: средний khaan."},{"th":"พุธ","rom":"phút","ru":"среда","how":"พ это ph, низкий класс. ุ краткое у. ธ на конце глухое т. Короткий глухой слог низкого класса без знака: высокий phút."},{"th":"พฤหัสบดี","rom":"phrʉ́-hàt-sà-bɔɔ-dii","ru":"четверг","how":"Четыре слога: phrʉ́ высокий, hàt низкий, sà низкий, bɔɔ-dii средний-средний. ฤ в первом слоге даёт звук ʉ, отдельное «р» перед ним слабое. ห во втором слоге слышна как h. Конец บดี читается bɔɔ-dii. Запоминайте слогами, не по одной букве подряд."},{"th":"ศุกร์","rom":"sùk","ru":"пятница","how":"ศ высокий класс, читается s. ุ краткое у. ก глухое к. ร์ на конце не читается. Короткий глухой слог высокого класса: низкий sùk."},{"th":"เสาร์","rom":"sǎo","ru":"суббота","how":"ส высокий класс. เ и า дают ao. ร์ не читается. Живой слог без знака: восходящий sǎo."},{"th":"อาทิตย์","rom":"aa-thít","ru":"воскресенье","how":"อา: อ и า, долгий средний aa. ทิ: ท это th, ิ краткое и, ต глухое т. Короткий глухой слог низкого класса: высокий thít. ย์ на конце не читается."},{"th":"ชั่วโมง","rom":"chûa-moong","ru":"час, длительность","how":"ชั่ว: ช низкий класс, гласный ua, ่ май-эк: падающий chûa. โมง moong средний, тот же слог, что в циферблате. สองชั่วโมง «два часа». Это длина, не время на часах."},{"th":"แปด","rom":"bpɛ̀ɛt","ru":"восемь","how":"ป это bp без выдоха. แ долгое открытое э. ด глухое т. Знака нет. Долгий глухой слог среднего класса: низкий bpɛ̀ɛt."},{"th":"เจ็ด","rom":"jèt","ru":"семь","how":"จ это j, средний класс. เ и ็ краткое э. ด глухое т. Короткий глухой слог среднего класса: низкий jèt."},{"th":"สี่","rom":"sìi","ru":"четыре","how":"ส высокий класс. ี долгое и. ่ май-эк. Высокий класс плюс май-эк: низкий sìi."},{"th":"ห้า","rom":"hâa","ru":"пять","how":"ห это h, высокий класс. ้ май-тхо. า долгое а. Высокий класс плюс май-тхо: падающий hâa."},{"th":"หก","rom":"hòk","ru":"шесть","how":"ห высокий класс. Гласной на письме нет, слышится краткое о. ก глухое к. Короткий глухой слог высокого класса: низкий hòk."},{"th":"หนึ่ง","rom":"nʉ̀ng","ru":"один","how":"ห не читается и делает класс высоким. น это н. ึ краткое ʉ. ่ май-эк. ง это нг. Высокий класс плюс май-эк: низкий nʉ̀ng. В числе 11 будет не это слово, а เอ็ด."},{"th":"สอง","rom":"sɔ̌ɔng","ru":"два","how":"ส высокий класс. อ долгое открытое о. ง это нг. Живой слог без знака: восходящий sɔ̌ɔng. 20 говорят ยี่สิบ, не สองสิบ."},{"th":"ไป","rom":"bpai","ru":"идти, ехать туда","how":"ป читается bp: п без выдоха, один звук. ไ гласный ai. Средний класс, живой слог, знака нет: средний bpai."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."},{"th":"ได้","rom":"dâai","ru":"получилось; в ไม่ได้ меняет смысл от места","how":"ไ слева, гласный ai. ด это d. ้ это май-тхо. Средний класс плюс май-тхо дают падающий тон: dâai. Перед действием ไม่ได้ значит «не сделал». После действия ได้ значит «могу», ไม่ได้ значит «не могу»."},{"th":"เมื่อวาน","rom":"mʉ̂ʉa-waan","ru":"вчера","how":"Когда: เ, ื и อ вместе дают гласный ʉa, ม это м, ่ май-эк. Низкий класс плюс май-эк: падающий mʉ̂ʉa. วาน: ว это w, า долгое а, น это н. Низкий класс, живой слог, знака нет: средний waan. Всё слово ставьте в начало фразы."}],"diagrams":[{"title":"Восемь утра, тот же глагол","slots":[{"role":"когда","m":{"th":"แปดโมงเช้า","rom":"bpɛ̀ɛt moong cháao"},"f":{"th":"แปดโมงเช้า","rom":"bpɛ̀ɛt moong cháao"}},{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"действие","m":{"th":"ไป","rom":"bpai"},"f":{"th":"ไป","rom":"bpai"}}]}],"tables":[{"title":"Иду в восемь","cols":["да","нет","вопрос"],"rows":[{"h":"план","cells":[{"ru":"В восемь утра я иду.","m":{"th":"แปดโมงเช้าผมไปครับ","rom":"bpɛ̀ɛt moong cháao phǒm bpai khráp"},"f":{"th":"แปดโมงเช้าฉันไปค่ะ","rom":"bpɛ̀ɛt moong cháao chǎn bpai khâ"}},{"ru":"В восемь утра я не иду.","m":{"th":"แปดโมงเช้าผมไม่ไปครับ","rom":"bpɛ̀ɛt moong cháao phǒm mâi bpai khráp"},"f":{"th":"แปดโมงเช้าฉันไม่ไปค่ะ","rom":"bpɛ̀ɛt moong cháao chǎn mâi bpai khâ"}},{"ru":"В восемь утра ты идёшь?","m":{"th":"แปดโมงเช้าคุณไปไหมครับ","rom":"bpɛ̀ɛt moong cháao khun bpai mǎi khráp"},"f":{"th":"แปดโมงเช้าคุณไปไหมคะ","rom":"bpɛ̀ɛt moong cháao khun bpai mǎi khá"}}]},{"h":"вчера","cells":[{"ru":"Вчера в восемь утра я пошёл.","m":{"th":"เมื่อวานแปดโมงเช้าผมไปครับ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao phǒm bpai khráp"},"f":{"th":"เมื่อวานแปดโมงเช้าฉันไปค่ะ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao chǎn bpai khâ"}},{"ru":"Вчера в восемь утра я не пошёл.","m":{"th":"เมื่อวานแปดโมงเช้าผมไม่ได้ไปครับ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao phǒm mâi-dâai bpai khráp"},"f":{"th":"เมื่อวานแปดโมงเช้าฉันไม่ได้ไปค่ะ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao chǎn mâi-dâai bpai khâ"}},{"ru":"Вчера в восемь утра ты пошёл?","m":{"th":"เมื่อวานแปดโมงเช้าคุณไปไหมครับ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao khun bpai mǎi khráp"},"f":{"th":"เมื่อวานแปดโมงเช้าคุณไปไหมคะ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao khun bpai mǎi khá"}}]}]},{"title":"Скажите эти часы вслух","cols":["фраза"],"rows":[{"h":"7:00","cells":[{"ru":"Семь утра.","m":{"th":"เจ็ดโมงเช้าครับ","rom":"jèt moong cháao khráp"},"f":{"th":"เจ็ดโมงเช้าค่ะ","rom":"jèt moong cháao khâ"}}]},{"h":"8:00","cells":[{"ru":"Восемь утра.","m":{"th":"แปดโมงเช้าครับ","rom":"bpɛ̀ɛt moong cháao khráp"},"f":{"th":"แปดโมงเช้าค่ะ","rom":"bpɛ̀ɛt moong cháao khâ"}}]},{"h":"12:00","cells":[{"ru":"Полдень.","m":{"th":"เที่ยงครับ","rom":"thìang khráp"},"f":{"th":"เที่ยงค่ะ","rom":"thìang khâ"}}]},{"h":"13:00","cells":[{"ru":"Час дня.","m":{"th":"บ่ายโมงครับ","rom":"bàai moong khráp"},"f":{"th":"บ่ายโมงค่ะ","rom":"bàai moong khâ"}}]},{"h":"14:00","cells":[{"ru":"Два часа дня.","m":{"th":"บ่ายสองโมงครับ","rom":"bàai sɔ̌ɔng moong khráp"},"f":{"th":"บ่ายสองโมงค่ะ","rom":"bàai sɔ̌ɔng moong khâ"}}]},{"h":"16:00","cells":[{"ru":"Четыре вечера.","m":{"th":"สี่โมงเย็นครับ","rom":"sìi moong yen khráp"},"f":{"th":"สี่โมงเย็นค่ะ","rom":"sìi moong yen khâ"}}]},{"h":"17:00","cells":[{"ru":"Пять вечера.","m":{"th":"ห้าโมงเย็นครับ","rom":"hâa moong yen khráp"},"f":{"th":"ห้าโมงเย็นค่ะ","rom":"hâa moong yen khâ"}}]},{"h":"18:00","cells":[{"ru":"Шесть вечера.","m":{"th":"หกโมงเย็นครับ","rom":"hòk moong yen khráp"},"f":{"th":"หกโมงเย็นค่ะ","rom":"hòk moong yen khâ"}}]},{"h":"19:00","cells":[{"ru":"Семь вечера.","m":{"th":"หนึ่งทุ่มครับ","rom":"nʉ̀ng thûm khráp"},"f":{"th":"หนึ่งทุ่มค่ะ","rom":"nʉ̀ng thûm khâ"}}]},{"h":"20:00","cells":[{"ru":"Восемь вечера.","m":{"th":"สองทุ่มครับ","rom":"sɔ̌ɔng thûm khráp"},"f":{"th":"สองทุ่มค่ะ","rom":"sɔ̌ɔng thûm khâ"}}]},{"h":"1:00","cells":[{"ru":"Час ночи.","m":{"th":"ตีหนึ่งครับ","rom":"dtii nʉ̀ng khráp"},"f":{"th":"ตีหนึ่งค่ะ","rom":"dtii nʉ̀ng khâ"}}]}]},{"title":"День","cols":["вопрос","ответ"],"rows":[{"h":"сегодня","cells":[{"ru":"Какой сегодня день?","m":{"th":"วันนี้วันอะไรครับ","rom":"wan-níi wan à-rai khráp"},"f":{"th":"วันนี้วันอะไรคะ","rom":"wan-níi wan à-rai khá"}},{"ru":"Сегодня понедельник.","m":{"th":"วันนี้วันจันทร์ครับ","rom":"wan-níi wan-jan khráp"},"f":{"th":"วันนี้วันจันทร์ค่ะ","rom":"wan-níi wan-jan khâ"}}]},{"h":"завтра","cells":[{"ru":"Какой завтра день?","m":{"th":"พรุ่งนี้วันอะไรครับ","rom":"phrûng-níi wan à-rai khráp"},"f":{"th":"พรุ่งนี้วันอะไรคะ","rom":"phrûng-níi wan à-rai khá"}},{"ru":"Завтра вторник.","m":{"th":"พรุ่งนี้วันอังคารครับ","rom":"phrûng-níi wan ang-khaan khráp"},"f":{"th":"พรุ่งนี้วันอังคารค่ะ","rom":"phrûng-níi wan ang-khaan khâ"}}]}]}],"drills":[{"ru":"Сейчас восемь утра.","m":{"th":"ตอนนี้แปดโมงเช้าครับ","rom":"dtɔɔn-níi bpɛ̀ɛt moong cháao khráp"},"f":{"th":"ตอนนี้แปดโมงเช้าค่ะ","rom":"dtɔɔn-níi bpɛ̀ɛt moong cháao khâ"}},{"ru":"В восемь утра я иду.","m":{"th":"แปดโมงเช้าผมไปครับ","rom":"bpɛ̀ɛt moong cháao phǒm bpai khráp"},"f":{"th":"แปดโมงเช้าฉันไปค่ะ","rom":"bpɛ̀ɛt moong cháao chǎn bpai khâ"}},{"ru":"Вчера в восемь утра я не пошёл.","m":{"th":"เมื่อวานแปดโมงเช้าผมไม่ได้ไปครับ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao phǒm mâi-dâai bpai khráp"},"f":{"th":"เมื่อวานแปดโมงเช้าฉันไม่ได้ไปค่ะ","rom":"mʉ̂ʉa-waan bpɛ̀ɛt moong cháao chǎn mâi-dâai bpai khâ"}},{"ru":"Какой сегодня день?","m":{"th":"วันนี้วันอะไรครับ","rom":"wan-níi wan à-rai khráp"},"f":{"th":"วันนี้วันอะไรคะ","rom":"wan-níi wan à-rai khá"}},{"ru":"Сегодня понедельник.","m":{"th":"วันนี้วันจันทร์ครับ","rom":"wan-níi wan-jan khráp"},"f":{"th":"วันนี้วันจันทร์ค่ะ","rom":"wan-níi wan-jan khâ"}},{"ru":"Семь вечера.","m":{"th":"หนึ่งทุ่มครับ","rom":"nʉ̀ng thûm khráp"},"f":{"th":"หนึ่งทุ่มค่ะ","rom":"nʉ̀ng thûm khâ"}},{"ru":"Полдень.","m":{"th":"เที่ยงครับ","rom":"thìang khráp"},"f":{"th":"เที่ยงค่ะ","rom":"thìang khâ"}},{"ru":"Два часа.","m":{"th":"สองชั่วโมงครับ","rom":"sɔ̌ɔng chûa-moong khráp"},"f":{"th":"สองชั่วโมงค่ะ","rom":"sɔ̌ɔng chûa-moong khâ"}}],"self":"Скажите, который сейчас час вашей фразой, какой сегодня день и во сколько вы сегодня едите. Глагол не меняйте, меняйте только рамку времени."},{"id":9,"title":"Сказать, что есть и чего нет","goal":"Сказать, что где-то есть вода, что у вас есть деньги и время, и чего нет.","petrov":"Девятый шаг Петрова: «имеется». Это มี, не связка «я есть учитель».","formula":"Место или хозяин, потом มี, потом что. Отрицание: ไม่มี, одним словом перед вещью. Вопрос: ไหม в конце. ที่นี่ «здесь» — оба слога падают.","note":"ผมมีเงิน «у меня есть деньги». ผมเป็นครู из третьего урока этой фразой не заменяется.","lead":{"ru":"Здесь есть вода.","m":{"th":"ที่นี่มีน้ำครับ","rom":"thîi-nîi mii náam khráp"},"f":{"th":"ที่นี่มีน้ำค่ะ","rom":"thîi-nîi mii náam khâ"}},"words":[{"th":"มี","rom":"mii","ru":"имеется, есть у кого-то","how":"ม это м. ี долгое и. Низкий класс, живой слог, знака нет: средний mii. Отрицание: ไม่มี. Это не связка «я есть учитель»."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."},{"th":"ที่นี่","rom":"thîi-nîi","ru":"здесь","how":"ที่ thîi падает. Второй слог тоже с май-эк, не с май-тхо, и тоже падает: nîi. Оба слога падающие. Это не นี้ из слова «завтра»."},{"th":"ที่","rom":"thîi","ru":"место; также служебное слово","how":"ท это th: т с выдохом, не английское think. ี долгое и. ่ май-эк. Низкий класс плюс май-эк: падающий thîi."},{"th":"นี่","rom":"nîi","ru":"вот это","how":"น это н. ี долгое и. ่ май-эк. Низкий класс плюс май-эк: падающий nîi. Этим начинают фразу, показывая на вещь: นี่บ้านผม. Не путайте с นี้ níi, высокий, которое стоит после слова."},{"th":"น้ำ","rom":"náam","ru":"вода","how":"น низкий класс. ้ май-тхо. ำ это долгое ам. Низкий класс плюс май-тхо: высокий náam."},{"th":"เงิน","rom":"ngən","ru":"деньги","how":"ง начинает слог, это ng. เ и ิ дают гласный ə. น это н. Низкий класс, живой слог: средний ngən."},{"th":"เวลา","rom":"wee-laa","ru":"время","how":"เว: ว низкий класс и гласный э, живой слог, средний wee. ลา: ล низкий класс, า долгое а, средний laa. Оба средних."},{"th":"คน","rom":"khon","ru":"человек; счётное слово для людей","how":"ค это kh. Гласной на письме нет, слышится краткое о. น это н. Низкий класс, живой слог: средний khon. คนสามคน «людей три человека»."},{"th":"บ้าน","rom":"bâan","ru":"дом","how":"บ это b, средний класс. ้ май-тхо. า долгое а. น это н. Средний класс плюс май-тхо: падающий bâan."}],"diagrams":[{"title":"Здесь есть","slots":[{"role":"где","m":{"th":"ที่นี่","rom":"thîi-nîi"},"f":{"th":"ที่นี่","rom":"thîi-nîi"}},{"role":"имеется","m":{"th":"มี","rom":"mii"},"f":{"th":"มี","rom":"mii"}},{"role":"что","m":{"th":"น้ำ","rom":"náam"},"f":{"th":"น้ำ","rom":"náam"}}]}],"tables":[{"title":"Есть и нет","cols":["да","нет","вопрос"],"rows":[{"h":"здесь","cells":[{"ru":"Здесь есть вода.","m":{"th":"ที่นี่มีน้ำครับ","rom":"thîi-nîi mii náam khráp"},"f":{"th":"ที่นี่มีน้ำค่ะ","rom":"thîi-nîi mii náam khâ"}},{"ru":"Здесь нет воды.","m":{"th":"ที่นี่ไม่มีน้ำครับ","rom":"thîi-nîi mâi-mii náam khráp"},"f":{"th":"ที่นี่ไม่มีน้ำค่ะ","rom":"thîi-nîi mâi-mii náam khâ"}},{"ru":"Здесь есть вода?","m":{"th":"ที่นี่มีน้ำไหมครับ","rom":"thîi-nîi mii náam mǎi khráp"},"f":{"th":"ที่นี่มีน้ำไหมคะ","rom":"thîi-nîi mii náam mǎi khá"}}]},{"h":"деньги","cells":[{"ru":"У меня есть деньги.","m":{"th":"ผมมีเงินครับ","rom":"phǒm mii ngən khráp"},"f":{"th":"ฉันมีเงินค่ะ","rom":"chǎn mii ngən khâ"}},{"ru":"У меня нет денег.","m":{"th":"ผมไม่มีเงินครับ","rom":"phǒm mâi-mii ngən khráp"},"f":{"th":"ฉันไม่มีเงินค่ะ","rom":"chǎn mâi-mii ngən khâ"}},{"ru":"У тебя есть деньги?","m":{"th":"คุณมีเงินไหมครับ","rom":"khun mii ngən mǎi khráp"},"f":{"th":"คุณมีเงินไหมคะ","rom":"khun mii ngən mǎi khá"}}]},{"h":"время","cells":[{"ru":"У меня есть время.","m":{"th":"ผมมีเวลาครับ","rom":"phǒm mii wee-laa khráp"},"f":{"th":"ฉันมีเวลาค่ะ","rom":"chǎn mii wee-laa khâ"}},{"ru":"У меня нет времени.","m":{"th":"ผมไม่มีเวลาครับ","rom":"phǒm mâi-mii wee-laa khráp"},"f":{"th":"ฉันไม่มีเวลาค่ะ","rom":"chǎn mâi-mii wee-laa khâ"}},{"ru":"У тебя есть время?","m":{"th":"คุณมีเวลาไหมครับ","rom":"khun mii wee-laa mǎi khráp"},"f":{"th":"คุณมีเวลาไหมคะ","rom":"khun mii wee-laa mǎi khá"}}]}]}],"drills":[{"ru":"Здесь есть вода.","m":{"th":"ที่นี่มีน้ำครับ","rom":"thîi-nîi mii náam khráp"},"f":{"th":"ที่นี่มีน้ำค่ะ","rom":"thîi-nîi mii náam khâ"}},{"ru":"Здесь нет воды.","m":{"th":"ที่นี่ไม่มีน้ำครับ","rom":"thîi-nîi mâi-mii náam khráp"},"f":{"th":"ที่นี่ไม่มีน้ำค่ะ","rom":"thîi-nîi mâi-mii náam khâ"}},{"ru":"Здесь есть вода?","m":{"th":"ที่นี่มีน้ำไหมครับ","rom":"thîi-nîi mii náam mǎi khráp"},"f":{"th":"ที่นี่มีน้ำไหมคะ","rom":"thîi-nîi mii náam mǎi khá"}},{"ru":"У меня нет денег.","m":{"th":"ผมไม่มีเงินครับ","rom":"phǒm mâi-mii ngən khráp"},"f":{"th":"ฉันไม่มีเงินค่ะ","rom":"chǎn mâi-mii ngən khâ"}},{"ru":"У меня есть время.","m":{"th":"ผมมีเวลาครับ","rom":"phǒm mii wee-laa khráp"},"f":{"th":"ฉันมีเวลาค่ะ","rom":"chǎn mii wee-laa khâ"}},{"ru":"У тебя есть время?","m":{"th":"คุณมีเวลาไหมครับ","rom":"khun mii wee-laa mǎi khráp"},"f":{"th":"คุณมีเวลาไหมคะ","rom":"khun mii wee-laa mǎi khá"}}],"self":"Скажите про комнату, где вы сидите: что в ней есть и чего нет. Потом про себя: есть ли время и деньги."},{"id":10,"title":"Сказать, куда идти","goal":"Сказать «домой», «налево», «прямо», «далеко» и «я пришёл из дома».","petrov":"Десятый шаг Петрова: направление. Те же ไป и มา, место после них. Признак «далеко» снова без связки.","formula":"ไป плюс место: ไปบ้าน. มาจาก «пришёл из». เลี้ยวซ้าย, เลี้ยวขวา, ตรงไป. Далеко и близко: บ้านไกล, บ้านอยู่ใกล้.","note":"ไป от говорящего, มา к говорящему. В ตรง ร часто почти не слышно: dtrong или dtong, тон средний.","lead":{"ru":"Налево.","m":{"th":"เลี้ยวซ้ายครับ","rom":"líao sáai khráp"},"f":{"th":"เลี้ยวซ้ายค่ะ","rom":"líao sáai khâ"}},"words":[{"th":"ไป","rom":"bpai","ru":"идти, ехать туда","how":"ป читается bp: п без выдоха, один звук. ไ гласный ai. Средний класс, живой слог, знака нет: средний bpai."},{"th":"มา","rom":"maa","ru":"приходить, сюда","how":"ม это м, низкий класс. า долгое а. Знака нет, живой слог: средний maa. Рядом с другим глаголом показывает направление к говорящему."},{"th":"บ้าน","rom":"bâan","ru":"дом","how":"บ это b, средний класс. ้ май-тхо. า долгое а. น это н. Средний класс плюс май-тхо: падающий bâan."},{"th":"เลี้ยว","rom":"líao","ru":"поворачивать","how":"ล низкий класс. เ, ี, ย и ว дают гласный iao. ้ май-тхо. Низкий класс плюс май-тхо: высокий líao. เลี้ยวซ้าย «налево», เลี้ยวขวา «направо»."},{"th":"ซ้าย","rom":"sáai","ru":"лево","how":"ซ это s, низкий класс. ้ май-тхо. า долгое а. ย закрывает слог. Низкий класс плюс май-тхо: высокий sáai."},{"th":"ขวา","rom":"khwǎa","ru":"право","how":"ข высокий класс, kh. ว это w внутри слога. า долгое а. Живой слог без знака: восходящий khwǎa."},{"th":"ตรง","rom":"dtrong","ru":"прямо","how":"ต это dt. ร в речи слабое, часто слышится dtong. Гласный краткий о. ง это нг. Средний класс, живой слог: средний dtrong. ตรงไป «прямо»."},{"th":"ไกล","rom":"glai","ru":"далеко","how":"ก это g, ล это l, вместе gl. ไ гласный ai. Средний класс, живой слог: средний glai. Признак без связки: บ้านไกล «дом далеко»."},{"th":"ใกล้","rom":"glâi","ru":"близко","how":"Те же ก и ล. ้ май-тхо. ใ гласный ai. Средний класс плюс май-тхо: падающий glâi."},{"th":"ถึง","rom":"thʉ̌ng","ru":"до, добраться","how":"ถ это th, высокий класс. ึ краткое ʉ. ง это нг. Живой слог без знака: восходящий thʉ̌ng. ถึงบ้าน «до дома, добрался домой»."},{"th":"กลับ","rom":"glàp","ru":"возвращаться","how":"ก и ล вместе gl. ั краткое а. บ глухое п. Средний класс, короткий глухой слог: низкий glàp."},{"th":"จาก","rom":"jàak","ru":"от, из","how":"จ средний класс. า долгое а. ก глухое к. Долгий глухой слог среднего класса без знака: низкий jàak. มาจากบ้าน «пришёл из дома»."},{"th":"รถ","rom":"rót","ru":"машина, автобус","how":"ร низкий класс. Гласный краткий о. ถ на конце глухое т, не th. Короткий глухой слог низкого класса: высокий rót."},{"th":"อยู่","rom":"yùu","ru":"находиться","how":"Первая буква อ не даёт отдельного слога: она задаёт средний класс, звук начинается с ย, это y. ู долгое у. ่ май-эк. Средний класс плюс май-эк: низкий yùu. Место стоит после: อยู่บ้าน «дома»."},{"th":"ขึ้น","rom":"khʉ̂n","ru":"вверх","how":"ข высокий класс. ึ краткое ʉ. ้ май-тхо. น это н. Высокий класс плюс май-тхо: падающий khʉ̂n."},{"th":"ลง","rom":"long","ru":"вниз","how":"ล низкий класс. Гласный краткий о. ง это нг. Живой слог без знака: средний long."},{"th":"เข้า","rom":"khâo","ru":"входить","how":"Те же буквы и тот же падающий khâo, что первая часть เข้าใจ. Здесь это отдельное действие «входить». ออก «выходить»: อ долгое о и глухое к, низкий ɔ̀ɔk, знака тона нет, тон даёт долгий глухой слог среднего класса."},{"th":"ออก","rom":"ɔ̀ɔk","ru":"выходить","how":"Две อ дают долгое открытое о, средний класс. ก глухое к. Знака нет. Долгий глухой слог: низкий ɔ̀ɔk."},{"th":"เดิน","rom":"dəən","ru":"идти пешком","how":"ด средний класс. เ и ิ дают гласный əə. น это н. Живой слог без знака: средний dəən."}],"diagrams":[{"title":"Налево","slots":[{"role":"действие","m":{"th":"เลี้ยว","rom":"líao"},"f":{"th":"เลี้ยว","rom":"líao"}},{"role":"куда","m":{"th":"ซ้าย","rom":"sáai"},"f":{"th":"ซ้าย","rom":"sáai"}}]}],"tables":[{"title":"Домой и далеко","cols":["да","нет","вопрос"],"rows":[{"h":"домой","cells":[{"ru":"Я иду домой.","m":{"th":"ผมไปบ้านครับ","rom":"phǒm bpai bâan khráp"},"f":{"th":"ฉันไปบ้านค่ะ","rom":"chǎn bpai bâan khâ"}},{"ru":"Я не иду домой.","m":{"th":"ผมไม่ไปบ้านครับ","rom":"phǒm mâi bpai bâan khráp"},"f":{"th":"ฉันไม่ไปบ้านค่ะ","rom":"chǎn mâi bpai bâan khâ"}},{"ru":"Ты идёшь домой?","m":{"th":"คุณไปบ้านไหมครับ","rom":"khun bpai bâan mǎi khráp"},"f":{"th":"คุณไปบ้านไหมคะ","rom":"khun bpai bâan mǎi khá"}}]},{"h":"далеко","cells":[{"ru":"Дом далеко.","m":{"th":"บ้านไกลครับ","rom":"bâan glai khráp"},"f":{"th":"บ้านไกลค่ะ","rom":"bâan glai khâ"}},{"ru":"Дом недалеко.","m":{"th":"บ้านไม่ไกลครับ","rom":"bâan mâi glai khráp"},"f":{"th":"บ้านไม่ไกลค่ะ","rom":"bâan mâi glai khâ"}},{"ru":"Дом далеко?","m":{"th":"บ้านไกลไหมครับ","rom":"bâan glai mǎi khráp"},"f":{"th":"บ้านไกลไหมคะ","rom":"bâan glai mǎi khá"}}]},{"h":"близко","cells":[{"ru":"Дом близко.","m":{"th":"บ้านอยู่ใกล้ครับ","rom":"bâan yùu glâi khráp"},"f":{"th":"บ้านอยู่ใกล้ค่ะ","rom":"bâan yùu glâi khâ"}},{"ru":"Дом не близко.","m":{"th":"บ้านไม่ใกล้ครับ","rom":"bâan mâi glâi khráp"},"f":{"th":"บ้านไม่ใกล้ค่ะ","rom":"bâan mâi glâi khâ"}},{"ru":"Дом близко?","m":{"th":"บ้านอยู่ใกล้ไหมครับ","rom":"bâan yùu glâi mǎi khráp"},"f":{"th":"บ้านอยู่ใกล้ไหมคะ","rom":"bâan yùu glâi mǎi khá"}}]}]},{"title":"Команды и откуда","cols":["фраза"],"rows":[{"h":"направо","cells":[{"ru":"Направо.","m":{"th":"เลี้ยวขวาครับ","rom":"líao khwǎa khráp"},"f":{"th":"เลี้ยวขวาค่ะ","rom":"líao khwǎa khâ"}}]},{"h":"прямо","cells":[{"ru":"Прямо.","m":{"th":"ตรงไปครับ","rom":"dtrong bpai khráp"},"f":{"th":"ตรงไปค่ะ","rom":"dtrong bpai khâ"}}]},{"h":"пешком","cells":[{"ru":"Идите прямо.","m":{"th":"เดินตรงไปครับ","rom":"dəən dtrong bpai khráp"},"f":{"th":"เดินตรงไปค่ะ","rom":"dəən dtrong bpai khâ"}}]},{"h":"из дома","cells":[{"ru":"Я пришёл из дома.","m":{"th":"ผมมาจากบ้านครับ","rom":"phǒm maa jàak bâan khráp"},"f":{"th":"ฉันมาจากบ้านค่ะ","rom":"chǎn maa jàak bâan khâ"}}]},{"h":"добрался","cells":[{"ru":"Я добрался домой.","m":{"th":"ผมถึงบ้านครับ","rom":"phǒm thʉ̌ng bâan khráp"},"f":{"th":"ฉันถึงบ้านค่ะ","rom":"chǎn thʉ̌ng bâan khâ"}}]},{"h":"назад","cells":[{"ru":"Я возвращаюсь домой.","m":{"th":"ผมกลับบ้านครับ","rom":"phǒm glàp bâan khráp"},"f":{"th":"ฉันกลับบ้านค่ะ","rom":"chǎn glàp bâan khâ"}}]},{"h":"войти","cells":[{"ru":"Входите.","m":{"th":"เข้าบ้านครับ","rom":"khâo bâan khráp"},"f":{"th":"เข้าบ้านค่ะ","rom":"khâo bâan khâ"}}]},{"h":"выйти","cells":[{"ru":"Выходите из дома.","m":{"th":"ออกจากบ้านครับ","rom":"ɔ̀ɔk jàak bâan khráp"},"f":{"th":"ออกจากบ้านค่ะ","rom":"ɔ̀ɔk jàak bâan khâ"}}]},{"h":"вверх","cells":[{"ru":"Вверх.","m":{"th":"ขึ้นไปครับ","rom":"khʉ̂n bpai khráp"},"f":{"th":"ขึ้นไปค่ะ","rom":"khʉ̂n bpai khâ"}}]},{"h":"вниз","cells":[{"ru":"Вниз.","m":{"th":"ลงไปครับ","rom":"long bpai khráp"},"f":{"th":"ลงไปค่ะ","rom":"long bpai khâ"}}]},{"h":"машина","cells":[{"ru":"Где машина?","m":{"th":"รถอยู่ที่ไหนครับ","rom":"rót yùu thîi-nǎi khráp"},"f":{"th":"รถอยู่ที่ไหนคะ","rom":"rót yùu thîi-nǎi khá"}}]}]}],"drills":[{"ru":"Налево.","m":{"th":"เลี้ยวซ้ายครับ","rom":"líao sáai khráp"},"f":{"th":"เลี้ยวซ้ายค่ะ","rom":"líao sáai khâ"}},{"ru":"Направо.","m":{"th":"เลี้ยวขวาครับ","rom":"líao khwǎa khráp"},"f":{"th":"เลี้ยวขวาค่ะ","rom":"líao khwǎa khâ"}},{"ru":"Прямо.","m":{"th":"ตรงไปครับ","rom":"dtrong bpai khráp"},"f":{"th":"ตรงไปค่ะ","rom":"dtrong bpai khâ"}},{"ru":"Я иду домой.","m":{"th":"ผมไปบ้านครับ","rom":"phǒm bpai bâan khráp"},"f":{"th":"ฉันไปบ้านค่ะ","rom":"chǎn bpai bâan khâ"}},{"ru":"Дом далеко?","m":{"th":"บ้านไกลไหมครับ","rom":"bâan glai mǎi khráp"},"f":{"th":"บ้านไกลไหมคะ","rom":"bâan glai mǎi khá"}},{"ru":"Я пришёл из дома.","m":{"th":"ผมมาจากบ้านครับ","rom":"phǒm maa jàak bâan khráp"},"f":{"th":"ฉันมาจากบ้านค่ะ","rom":"chǎn maa jàak bâan khâ"}},{"ru":"Я возвращаюсь домой.","m":{"th":"ผมกลับบ้านครับ","rom":"phǒm glàp bâan khráp"},"f":{"th":"ฉันกลับบ้านค่ะ","rom":"chǎn glàp bâan khâ"}},{"ru":"Где дом?","m":{"th":"บ้านอยู่ที่ไหนครับ","rom":"bâan yùu thîi-nǎi khráp"},"f":{"th":"บ้านอยู่ที่ไหนคะ","rom":"bâan yùu thîi-nǎi khá"}}],"self":"Объясните дорогу от двери до вашего стула: прямо, налево или направо, близко или далеко. Потом скажите, откуда вы сегодня пришли и куда вернётесь."},{"id":11,"title":"Сказать «могу», «надо» и «хочу»","goal":"На одном глаголе «иду» сказать: могу, не могу, не пошёл, надо, хочу и стоит.","petrov":"Одиннадцатый шаг Петрова: могу, надо, стоит. В тайском место слова меняет смысл, поэтому вся таблица на одном ไป.","formula":"После глагола: ไปได้ «могу пойти», ไปไม่ได้ «не могу». Перед глаголом: ไม่ได้ไป «не пошёл». ต้องไป «надо», ไม่ต้องไป «не надо». อยากไป «хочу пойти». ควรไป «стоит пойти».","note":"Не меняйте места. ไปไม่ได้ и ไม่ได้ไป для русского уха оба «не», но это разные клетки. Хочу здесь อยาก, не จะ. จะ из первого урока значит «собираюсь, будет».","lead":{"ru":"Я не могу пойти.","m":{"th":"ผมไปไม่ได้ครับ","rom":"phǒm bpai mâi-dâai khráp"},"f":{"th":"ฉันไปไม่ได้ค่ะ","rom":"chǎn bpai mâi-dâai khâ"}},"words":[{"th":"ไป","rom":"bpai","ru":"идти, ехать туда","how":"ป читается bp: п без выдоха, один звук. ไ гласный ai. Средний класс, живой слог, знака нет: средний bpai."},{"th":"ได้","rom":"dâai","ru":"получилось; в ไม่ได้ меняет смысл от места","how":"ไ слева, гласный ai. ด это d. ้ это май-тхо. Средний класс плюс май-тхо дают падающий тон: dâai. Перед действием ไม่ได้ значит «не сделал». После действия ได้ значит «могу», ไม่ได้ значит «не могу»."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."},{"th":"ต้อง","rom":"dtɔ̂ɔng","ru":"надо","how":"ต это dt, средний класс. ้ май-тхо. อ долгое открытое о. ง это нг. Средний класс плюс май-тхо: падающий dtɔ̂ɔng. Стоит перед действием: ต้องไป «надо идти». Отрицание ไม่ต้อง «не надо»."},{"th":"อยาก","rom":"yàak","ru":"хотеть","how":"อ задаёт средний класс, звук начинается с ย. า долгое а. ก на конце глухое к. Знака нет. Средний класс и долгий глухой слог дают низкий тон: yàak. Перед другим действием: อยากกิน «хочу есть»."},{"th":"ควร","rom":"khuan","ru":"стоит, следует","how":"ค это kh. ว это w внутри слога. ร на конце слабое. Низкий класс, живой слог, знака нет: средний khuan. ควรไป «стоит пойти»."},{"th":"ผม","rom":"phǒm","ru":"я, мужской род","how":"Две буквы, гласной между ними на письме нет. ผ читается ph: п с выдохом. ม закрывает слог на м. Между ними краткое о. ผ высокого класса, слог живой, знака тона нет. Тон восходящий: phǒm."},{"th":"ฉัน","rom":"chǎn","ru":"я, женский род","how":"ฉ читается ch: ч с выдохом. ั это краткое а. น на конце н. Высокий класс, слог живой, знака нет. Тон восходящий: chǎn."}],"diagrams":[{"title":"Не могу","slots":[{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"действие","m":{"th":"ไป","rom":"bpai"},"f":{"th":"ไป","rom":"bpai"}},{"role":"не могу","m":{"th":"ไม่ได้","rom":"mâi-dâai"},"f":{"th":"ไม่ได้","rom":"mâi-dâai"}}]},{"title":"Не пошёл","slots":[{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"не сделал","m":{"th":"ไม่ได้","rom":"mâi-dâai"},"f":{"th":"ไม่ได้","rom":"mâi-dâai"}},{"role":"действие","m":{"th":"ไป","rom":"bpai"},"f":{"th":"ไป","rom":"bpai"}}]}],"tables":[{"title":"Один глагол, пять смыслов","cols":["да","нет","вопрос"],"rows":[{"h":"могу","cells":[{"ru":"Я могу пойти.","m":{"th":"ผมไปได้ครับ","rom":"phǒm bpai dâai khráp"},"f":{"th":"ฉันไปได้ค่ะ","rom":"chǎn bpai dâai khâ"}},{"ru":"Я не могу пойти.","m":{"th":"ผมไปไม่ได้ครับ","rom":"phǒm bpai mâi-dâai khráp"},"f":{"th":"ฉันไปไม่ได้ค่ะ","rom":"chǎn bpai mâi-dâai khâ"}},{"ru":"Ты можешь пойти?","m":{"th":"คุณไปได้ไหมครับ","rom":"khun bpai dâai mǎi khráp"},"f":{"th":"คุณไปได้ไหมคะ","rom":"khun bpai dâai mǎi khá"}}]},{"h":"сделал","cells":[{"ru":"Я пошёл.","m":{"th":"ผมไปครับ","rom":"phǒm bpai khráp"},"f":{"th":"ฉันไปค่ะ","rom":"chǎn bpai khâ"}},{"ru":"Я не пошёл.","m":{"th":"ผมไม่ได้ไปครับ","rom":"phǒm mâi-dâai bpai khráp"},"f":{"th":"ฉันไม่ได้ไปค่ะ","rom":"chǎn mâi-dâai bpai khâ"}},{"ru":"Ты пошёл?","m":{"th":"คุณไปไหมครับ","rom":"khun bpai mǎi khráp"},"f":{"th":"คุณไปไหมคะ","rom":"khun bpai mǎi khá"}}]},{"h":"надо","cells":[{"ru":"Мне надо пойти.","m":{"th":"ผมต้องไปครับ","rom":"phǒm dtɔ̂ɔng bpai khráp"},"f":{"th":"ฉันต้องไปค่ะ","rom":"chǎn dtɔ̂ɔng bpai khâ"}},{"ru":"Мне не надо идти.","m":{"th":"ผมไม่ต้องไปครับ","rom":"phǒm mâi dtɔ̂ɔng bpai khráp"},"f":{"th":"ฉันไม่ต้องไปค่ะ","rom":"chǎn mâi dtɔ̂ɔng bpai khâ"}},{"ru":"Тебе надо идти?","m":{"th":"คุณต้องไปไหมครับ","rom":"khun dtɔ̂ɔng bpai mǎi khráp"},"f":{"th":"คุณต้องไปไหมคะ","rom":"khun dtɔ̂ɔng bpai mǎi khá"}}]},{"h":"хочу","cells":[{"ru":"Я хочу пойти.","m":{"th":"ผมอยากไปครับ","rom":"phǒm yàak bpai khráp"},"f":{"th":"ฉันอยากไปค่ะ","rom":"chǎn yàak bpai khâ"}},{"ru":"Я не хочу идти.","m":{"th":"ผมไม่อยากไปครับ","rom":"phǒm mâi yàak bpai khráp"},"f":{"th":"ฉันไม่อยากไปค่ะ","rom":"chǎn mâi yàak bpai khâ"}},{"ru":"Ты хочешь пойти?","m":{"th":"คุณอยากไปไหมครับ","rom":"khun yàak bpai mǎi khráp"},"f":{"th":"คุณอยากไปไหมคะ","rom":"khun yàak bpai mǎi khá"}}]},{"h":"стоит","cells":[{"ru":"Мне стоит пойти.","m":{"th":"ผมควรไปครับ","rom":"phǒm khuan bpai khráp"},"f":{"th":"ฉันควรไปค่ะ","rom":"chǎn khuan bpai khâ"}},{"ru":"Мне не стоит идти.","m":{"th":"ผมไม่ควรไปครับ","rom":"phǒm mâi khuan bpai khráp"},"f":{"th":"ฉันไม่ควรไปค่ะ","rom":"chǎn mâi khuan bpai khâ"}},{"ru":"Тебе стоит пойти?","m":{"th":"คุณควรไปไหมครับ","rom":"khun khuan bpai mǎi khráp"},"f":{"th":"คุณควรไปไหมคะ","rom":"khun khuan bpai mǎi khá"}}]}]}],"drills":[{"ru":"Я могу пойти.","m":{"th":"ผมไปได้ครับ","rom":"phǒm bpai dâai khráp"},"f":{"th":"ฉันไปได้ค่ะ","rom":"chǎn bpai dâai khâ"}},{"ru":"Я не могу пойти.","m":{"th":"ผมไปไม่ได้ครับ","rom":"phǒm bpai mâi-dâai khráp"},"f":{"th":"ฉันไปไม่ได้ค่ะ","rom":"chǎn bpai mâi-dâai khâ"}},{"ru":"Я не пошёл.","m":{"th":"ผมไม่ได้ไปครับ","rom":"phǒm mâi-dâai bpai khráp"},"f":{"th":"ฉันไม่ได้ไปค่ะ","rom":"chǎn mâi-dâai bpai khâ"}},{"ru":"Мне надо пойти.","m":{"th":"ผมต้องไปครับ","rom":"phǒm dtɔ̂ɔng bpai khráp"},"f":{"th":"ฉันต้องไปค่ะ","rom":"chǎn dtɔ̂ɔng bpai khâ"}},{"ru":"Мне не надо идти.","m":{"th":"ผมไม่ต้องไปครับ","rom":"phǒm mâi dtɔ̂ɔng bpai khráp"},"f":{"th":"ฉันไม่ต้องไปค่ะ","rom":"chǎn mâi dtɔ̂ɔng bpai khâ"}},{"ru":"Я хочу пойти.","m":{"th":"ผมอยากไปครับ","rom":"phǒm yàak bpai khráp"},"f":{"th":"ฉันอยากไปค่ะ","rom":"chǎn yàak bpai khâ"}},{"ru":"Мне стоит пойти.","m":{"th":"ผมควรไปครับ","rom":"phǒm khuan bpai khráp"},"f":{"th":"ฉันควรไปค่ะ","rom":"chǎn khuan bpai khâ"}},{"ru":"Ты можешь пойти?","m":{"th":"คุณไปได้ไหมครับ","rom":"khun bpai dâai mǎi khráp"},"f":{"th":"คุณไปได้ไหมคะ","rom":"khun bpai dâai mǎi khá"}}],"self":"Про сегодняшний выход скажите пять фраз на ไป: могу или нет, пошёл или нет, надо ли, хочу ли, стоит ли. Следите, с какой стороны стоит ไม่ได้."},{"id":12,"title":"Сказать, что происходит сейчас","goal":"Сказать, что вы прямо сейчас едите, и что вчера в тот момент тоже ели.","petrov":"Двенадцатый шаг Петрова: процесс. กำลัง не делает прошедшее и будущее. Рамку времени ставите отдельно, глагол тот же.","formula":"ตอนนี้ + кто + กำลัง + действие + อยู่. Отрицание процесса чаще просто ไม่ перед действием: ตอนนี้ผมไม่กิน. Вопрос: คุณกำลังกินอยู่ไหม.","note":"Не ставьте กำลัง перед รัก, หิว, ชอบ и перед «жарко». Для них хватает ตอนนี้ผมหิว. อยู่ в конце этой схемы — то же слово, что «находиться», здесь оно закрывает процесс.","lead":{"ru":"Я сейчас ем.","m":{"th":"ตอนนี้ผมกำลังกินอยู่ครับ","rom":"dtɔɔn-níi phǒm gam-lang gin yùu khráp"},"f":{"th":"ตอนนี้ฉันกำลังกินอยู่ค่ะ","rom":"dtɔɔn-níi chǎn gam-lang gin yùu khâ"}},"words":[{"th":"กำลัง","rom":"gam-lang","ru":"в процессе, перед действием","how":"กำ: ก средний класс, ำ это am, живой слог, средний gam. ลัง: ล низкий класс, ั краткое а, ง это нг, живой слог, средний lang. Само по себе времени не делает. Рамку «сейчас» или «вчера» ставите отдельно. После действия часто стоит อยู่."},{"th":"อยู่","rom":"yùu","ru":"находиться","how":"Первая буква อ не даёт отдельного слога: она задаёт средний класс, звук начинается с ย, это y. ู долгое у. ่ май-эк. Средний класс плюс май-эк: низкий yùu. Место стоит после: อยู่บ้าน «дома»."},{"th":"ตอนนี้","rom":"dtɔɔn-níi","ru":"сейчас","how":"ตอน dtɔɔn средний и นี้ níi высокий. Время-рамка, глагол от него не меняется."},{"th":"กิน","rom":"gin","ru":"есть","how":"ก читается g: к без выдоха, не kh. ิ краткое и. น это н. Средний класс, слог живой. Тон средний: gin."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."},{"th":"ได้","rom":"dâai","ru":"получилось; в ไม่ได้ меняет смысл от места","how":"ไ слева, гласный ai. ด это d. ้ это май-тхо. Средний класс плюс май-тхо дают падающий тон: dâai. Перед действием ไม่ได้ значит «не сделал». После действия ได้ значит «могу», ไม่ได้ значит «не могу»."},{"th":"เมื่อวาน","rom":"mʉ̂ʉa-waan","ru":"вчера","how":"Когда: เ, ื и อ вместе дают гласный ʉa, ม это м, ่ май-эк. Низкий класс плюс май-эк: падающий mʉ̂ʉa. วาน: ว это w, า долгое а, น это н. Низкий класс, живой слог, знака нет: средний waan. Всё слово ставьте в начало фразы."},{"th":"ไหม","rom":"mǎi","ru":"ли, вопрос да или нет","how":"ห не читается: она только переводит слог в высокий класс. Звук начинается с м, гласный тот же ai, что в ไม่. Знака тона нет. Высокий класс и живой слог дают восходящий тон: mǎi. Стоит в конце фразы, перед ครับ khráp или คะ khá. С падающим ไม่ это разные слова."}],"diagrams":[{"title":"Сейчас ем","slots":[{"role":"когда","m":{"th":"ตอนนี้","rom":"dtɔɔn-níi"},"f":{"th":"ตอนนี้","rom":"dtɔɔn-níi"}},{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"процесс","m":{"th":"กำลัง","rom":"gam-lang"},"f":{"th":"กำลัง","rom":"gam-lang"}},{"role":"действие","m":{"th":"กิน","rom":"gin"},"f":{"th":"กิน","rom":"gin"}},{"role":"ещё идёт","m":{"th":"อยู่","rom":"yùu"},"f":{"th":"อยู่","rom":"yùu"}}]}],"tables":[{"title":"Процесс не меняет глагол","cols":["да","нет","вопрос"],"rows":[{"h":"сейчас","cells":[{"ru":"Я сейчас ем.","m":{"th":"ตอนนี้ผมกำลังกินอยู่ครับ","rom":"dtɔɔn-níi phǒm gam-lang gin yùu khráp"},"f":{"th":"ตอนนี้ฉันกำลังกินอยู่ค่ะ","rom":"dtɔɔn-níi chǎn gam-lang gin yùu khâ"}},{"ru":"Я сейчас не ем.","m":{"th":"ตอนนี้ผมไม่กินครับ","rom":"dtɔɔn-níi phǒm mâi gin khráp"},"f":{"th":"ตอนนี้ฉันไม่กินค่ะ","rom":"dtɔɔn-níi chǎn mâi gin khâ"}},{"ru":"Ты сейчас ешь?","m":{"th":"คุณกำลังกินอยู่ไหมครับ","rom":"khun gam-lang gin yùu mǎi khráp"},"f":{"th":"คุณกำลังกินอยู่ไหมคะ","rom":"khun gam-lang gin yùu mǎi khá"}}]},{"h":"вчера в тот момент","cells":[{"ru":"Вчера я как раз ел.","m":{"th":"เมื่อวานผมกำลังกินอยู่ครับ","rom":"mʉ̂ʉa-waan phǒm gam-lang gin yùu khráp"},"f":{"th":"เมื่อวานฉันกำลังกินอยู่ค่ะ","rom":"mʉ̂ʉa-waan chǎn gam-lang gin yùu khâ"}},{"ru":"Вчера я не ел.","m":{"th":"เมื่อวานผมไม่ได้กินครับ","rom":"mʉ̂ʉa-waan phǒm mâi-dâai gin khráp"},"f":{"th":"เมื่อวานฉันไม่ได้กินค่ะ","rom":"mʉ̂ʉa-waan chǎn mâi-dâai gin khâ"}},{"ru":"Вчера ты как раз ел?","m":{"th":"เมื่อวานคุณกำลังกินอยู่ไหมครับ","rom":"mʉ̂ʉa-waan khun gam-lang gin yùu mǎi khráp"},"f":{"th":"เมื่อวานคุณกำลังกินอยู่ไหมคะ","rom":"mʉ̂ʉa-waan khun gam-lang gin yùu mǎi khá"}}]}]}],"drills":[{"ru":"Я сейчас ем.","m":{"th":"ตอนนี้ผมกำลังกินอยู่ครับ","rom":"dtɔɔn-níi phǒm gam-lang gin yùu khráp"},"f":{"th":"ตอนนี้ฉันกำลังกินอยู่ค่ะ","rom":"dtɔɔn-níi chǎn gam-lang gin yùu khâ"}},{"ru":"Я сейчас не ем.","m":{"th":"ตอนนี้ผมไม่กินครับ","rom":"dtɔɔn-níi phǒm mâi gin khráp"},"f":{"th":"ตอนนี้ฉันไม่กินค่ะ","rom":"dtɔɔn-níi chǎn mâi gin khâ"}},{"ru":"Ты сейчас ешь?","m":{"th":"คุณกำลังกินอยู่ไหมครับ","rom":"khun gam-lang gin yùu mǎi khráp"},"f":{"th":"คุณกำลังกินอยู่ไหมคะ","rom":"khun gam-lang gin yùu mǎi khá"}},{"ru":"Вчера я как раз ел.","m":{"th":"เมื่อวานผมกำลังกินอยู่ครับ","rom":"mʉ̂ʉa-waan phǒm gam-lang gin yùu khráp"},"f":{"th":"เมื่อวานฉันกำลังกินอยู่ค่ะ","rom":"mʉ̂ʉa-waan chǎn gam-lang gin yùu khâ"}},{"ru":"Я сейчас голоден.","m":{"th":"ตอนนี้ผมหิวครับ","rom":"dtɔɔn-níi phǒm hǐu khráp"},"f":{"th":"ตอนนี้ฉันหิวค่ะ","rom":"dtɔɔn-níi chǎn hǐu khâ"}}],"self":"Скажите, что вы делаете в эту минуту, через กำลัง…อยู่. Потом ту же схему про вчерашний момент. Голод, любовь и «мне нравится» скажите без กำลัง."},{"id":13,"title":"Описать человека и погоду","goal":"Сказать, какая сегодня погода, кто устал, кто высокого роста, и почему.","petrov":"Тринадцатый шаг Петрова: люди, свойства и погода. Свойство — сказуемое. Причину и противопоставление ставите отдельными словами.","formula":"วันนี้ร้อน. ผมเหนื่อย. เขาสูง. Причина после: เพราะว่า. Противопоставление: แต่. ไม่ стоит перед свойством: ไม่ร้อน, ไม่เหนื่อย. У дождя ไม่ стоит перед ตก: ฝนไม่ตก.","note":"Один человек и много людей в третьем лице здесь одно слово เขา. Род не маркируется.","lead":{"ru":"Сегодня жарко.","m":{"th":"วันนี้ร้อนครับ","rom":"wan-níi rɔ́ɔn khráp"},"f":{"th":"วันนี้ร้อนค่ะ","rom":"wan-níi rɔ́ɔn khâ"}},"words":[{"th":"ร้อน","rom":"rɔ́ɔn","ru":"жарко","how":"ร низкий класс. ้ май-тхо. อ долгое о. น это н. Низкий класс плюс май-тхо: высокий rɔ́ɔn. Без связки: วันนี้ร้อน «сегодня жарко»."},{"th":"หนาว","rom":"nǎao","ru":"холодно","how":"ห не читается. Звук с н. า долгое а. ว закрывает слог. Высокий класс, живой слог без знака: восходящий nǎao."},{"th":"ฝน","rom":"fǒn","ru":"дождь","how":"ฝ это f, высокий класс. Гласный краткий о. น это н. Живой слог без знака: восходящий fǒn. ฝนตก «дождь идёт»: второй слог ตก dtòk, низкий."},{"th":"ตก","rom":"dtòk","ru":"падать","how":"ต это dt. Гласный краткий о. ก глухое к. Короткий глухой слог среднего класса: низкий dtòk."},{"th":"แดด","rom":"dɛ̀ɛt","ru":"солнце, жар солнца","how":"ด средний класс. แ долгое открытое э. Вторая ด глухое т. Знака нет. Долгий глухой слог среднего класса: низкий dɛ̀ɛt."},{"th":"เหนื่อย","rom":"nʉ̀ai","ru":"устал","how":"ห не читается и делает класс высоким. Звук с н. เ, ื, อ и ย дают гласный ʉai. ่ май-эк. Высокий класс плюс май-эк: низкий nʉ̀ai."},{"th":"สูง","rom":"sǔung","ru":"высокий ростом","how":"ส высокий класс. ู долгое у. ง это нг. Живой слог без знака: восходящий sǔung."},{"th":"เก่ง","rom":"gèng","ru":"умелый","how":"ก средний класс. เ гласный э. ่ май-эк. ง это нг. Средний класс плюс май-эк: низкий gèng."},{"th":"เพราะ","rom":"phrɔ́","ru":"потому что, первая часть เพราะว่า","how":"พ это ph. ร слабое. เ, า и ะ дают краткий гласный. Короткий глухой слог низкого класса без знака: высокий phrɔ́."},{"th":"ว่า","rom":"wâa","ru":"что; вторая часть เพราะว่า","how":"ว это w, низкий класс. ่ май-эк. า долгое а. Низкий класс плюс май-эк: падающий wâa. เพราะว่า целиком phrɔ́-wâa «потому что». Причина ставится после."},{"th":"แต่","rom":"dtɛ̀ɛ","ru":"но","how":"ต это dt, средний класс. แ долгое открытое э. ่ май-эк. Средний класс плюс май-эк: низкий dtɛ̀ɛ."},{"th":"วันนี้","rom":"wan-níi","ru":"сегодня","how":"วัน wan, средний, плюс นี้ níi, высокий. Второй слог с май-тхо, не падающий."},{"th":"เขา","rom":"khǎo","ru":"он, она, они","how":"ข это kh с выдохом, высокий класс. เ и า вместе дают гласный ao. Знака нет, живой слог: восходящий khǎo. Одно слово на «он», «она» и «они»."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."}],"diagrams":[{"title":"Потому что","slots":[{"role":"кто","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}},{"role":"состояние","m":{"th":"เหนื่อย","rom":"nʉ̀ai"},"f":{"th":"เหนื่อย","rom":"nʉ̀ai"}},{"role":"потому что","m":{"th":"เพราะว่า","rom":"phrɔ́-wâa"},"f":{"th":"เพราะว่า","rom":"phrɔ́-wâa"}},{"role":"причина","m":{"th":"วันนี้ร้อน","rom":"wan-níi rɔ́ɔn"},"f":{"th":"วันนี้ร้อน","rom":"wan-níi rɔ́ɔn"}}]}],"tables":[{"title":"Погода и люди","cols":["да","нет","вопрос"],"rows":[{"h":"жара","cells":[{"ru":"Сегодня жарко.","m":{"th":"วันนี้ร้อนครับ","rom":"wan-níi rɔ́ɔn khráp"},"f":{"th":"วันนี้ร้อนค่ะ","rom":"wan-níi rɔ́ɔn khâ"}},{"ru":"Сегодня не жарко.","m":{"th":"วันนี้ไม่ร้อนครับ","rom":"wan-níi mâi rɔ́ɔn khráp"},"f":{"th":"วันนี้ไม่ร้อนค่ะ","rom":"wan-níi mâi rɔ́ɔn khâ"}},{"ru":"Сегодня жарко?","m":{"th":"วันนี้ร้อนไหมครับ","rom":"wan-níi rɔ́ɔn mǎi khráp"},"f":{"th":"วันนี้ร้อนไหมคะ","rom":"wan-níi rɔ́ɔn mǎi khá"}}]},{"h":"дождь","cells":[{"ru":"Сегодня дождь.","m":{"th":"วันนี้ฝนตกครับ","rom":"wan-níi fǒn dtòk khráp"},"f":{"th":"วันนี้ฝนตกค่ะ","rom":"wan-níi fǒn dtòk khâ"}},{"ru":"Сегодня дождя нет.","m":{"th":"วันนี้ฝนไม่ตกครับ","rom":"wan-níi fǒn mâi dtòk khráp"},"f":{"th":"วันนี้ฝนไม่ตกค่ะ","rom":"wan-níi fǒn mâi dtòk khâ"}},{"ru":"Сегодня дождь?","m":{"th":"วันนี้ฝนตกไหมครับ","rom":"wan-níi fǒn dtòk mǎi khráp"},"f":{"th":"วันนี้ฝนตกไหมคะ","rom":"wan-níi fǒn dtòk mǎi khá"}}]},{"h":"усталость","cells":[{"ru":"Я устал.","m":{"th":"ผมเหนื่อยครับ","rom":"phǒm nʉ̀ai khráp"},"f":{"th":"ฉันเหนื่อยค่ะ","rom":"chǎn nʉ̀ai khâ"}},{"ru":"Я не устал.","m":{"th":"ผมไม่เหนื่อยครับ","rom":"phǒm mâi nʉ̀ai khráp"},"f":{"th":"ฉันไม่เหนื่อยค่ะ","rom":"chǎn mâi nʉ̀ai khâ"}},{"ru":"Ты устал?","m":{"th":"คุณเหนื่อยไหมครับ","rom":"khun nʉ̀ai mǎi khráp"},"f":{"th":"คุณเหนื่อยไหมคะ","rom":"khun nʉ̀ai mǎi khá"}}]},{"h":"рост","cells":[{"ru":"Он высокого роста.","m":{"th":"เขาสูงครับ","rom":"khǎo sǔung khráp"},"f":{"th":"เขาสูงค่ะ","rom":"khǎo sǔung khâ"}},{"ru":"Он не высокого роста.","m":{"th":"เขาไม่สูงครับ","rom":"khǎo mâi sǔung khráp"},"f":{"th":"เขาไม่สูงค่ะ","rom":"khǎo mâi sǔung khâ"}},{"ru":"Он высокого роста?","m":{"th":"เขาสูงไหมครับ","rom":"khǎo sǔung mǎi khráp"},"f":{"th":"เขาสูงไหมคะ","rom":"khǎo sǔung mǎi khá"}}]}]}],"drills":[{"ru":"Сегодня жарко.","m":{"th":"วันนี้ร้อนครับ","rom":"wan-níi rɔ́ɔn khráp"},"f":{"th":"วันนี้ร้อนค่ะ","rom":"wan-níi rɔ́ɔn khâ"}},{"ru":"Сегодня холодно.","m":{"th":"วันนี้หนาวครับ","rom":"wan-níi nǎao khráp"},"f":{"th":"วันนี้หนาวค่ะ","rom":"wan-níi nǎao khâ"}},{"ru":"Сегодня дождь.","m":{"th":"วันนี้ฝนตกครับ","rom":"wan-níi fǒn dtòk khráp"},"f":{"th":"วันนี้ฝนตกค่ะ","rom":"wan-níi fǒn dtòk khâ"}},{"ru":"Сегодня солнечно.","m":{"th":"วันนี้แดดครับ","rom":"wan-níi dɛ̀ɛt khráp"},"f":{"th":"วันนี้แดดค่ะ","rom":"wan-níi dɛ̀ɛt khâ"}},{"ru":"Я устал, потому что сегодня жарко.","m":{"th":"ผมเหนื่อยเพราะว่าวันนี้ร้อนครับ","rom":"phǒm nʉ̀ai phrɔ́-wâa wan-níi rɔ́ɔn khráp"},"f":{"th":"ฉันเหนื่อยเพราะว่าวันนี้ร้อนค่ะ","rom":"chǎn nʉ̀ai phrɔ́-wâa wan-níi rɔ́ɔn khâ"}},{"ru":"Сегодня жарко, но я не устал.","m":{"th":"วันนี้ร้อนครับ แต่ผมไม่เหนื่อยครับ","rom":"wan-níi rɔ́ɔn khráp dtɛ̀ɛ phǒm mâi nʉ̀ai khráp"},"f":{"th":"วันนี้ร้อนค่ะ แต่ฉันไม่เหนื่อยค่ะ","rom":"wan-níi rɔ́ɔn khâ dtɛ̀ɛ chǎn mâi nʉ̀ai khâ"}},{"ru":"Он умелый.","m":{"th":"เขาเก่งครับ","rom":"khǎo gèng khráp"},"f":{"th":"เขาเก่งค่ะ","rom":"khǎo gèng khâ"}},{"ru":"Сегодня жарко?","m":{"th":"วันนี้ร้อนไหมครับ","rom":"wan-níi rɔ́ɔn mǎi khráp"},"f":{"th":"วันนี้ร้อนไหมคะ","rom":"wan-níi rɔ́ɔn mǎi khá"}}],"self":"Опишите сегодняшнюю погоду и себя: устали или нет, и почему. Потом одного знакомого: высокий он или умелый. Связку не добавляйте."},{"id":14,"title":"Сказать «уже», «ещё нет» и «никогда»","goal":"Сказать, что уже поели, ещё нет, доводилось или никогда, и что только что закончили.","petrov":"Четырнадцатый шаг Петрова: опыт и «уже». Это не окончание прошедшего времени. «Вчера любил» по-прежнему говорят через เมื่อวาน и тот же глагол.","formula":"Уже: действие + แล้ว. Ещё нет: ยังไม่ перед действием. Вопрос «уже?»: действие + หรือยัง. Доводилось: เคย перед действием. Никогда: ไม่เคย. Только что: เพิ่ง. Закончил: เสร็จแล้ว.","note":"Короткий ответ на «уже поел?»: แล้วครับ lɛ́ɛo khráp или ยังครับ yang khráp. Женщине: แล้วค่ะ lɛ́ɛo khâ или ยังค่ะ yang khâ. Не отвечайте на этот вопрос словом ใช่.","lead":{"ru":"Ты уже поел?","m":{"th":"กินหรือยังครับ","rom":"gin rʉ̌ʉ-yang khráp"},"f":{"th":"กินหรือยังคะ","rom":"gin rʉ̌ʉ-yang khá"}},"words":[{"th":"แล้ว","rom":"lɛ́ɛo","ru":"уже","how":"ล низкий класс. แ долгое открытое э. ้ май-тхо. ว достраивает гласный. Низкий класс плюс май-тхо: высокий lɛ́ɛo. Это не окончание прошедшего времени. Смысл: дело дошло до новой точки, «уже»."},{"th":"ยัง","rom":"yang","ru":"ещё","how":"ย низкий класс. ั краткое а. ง это нг. Живой слог без знака: средний yang. ยังไม่ «ещё нет». Короткий ответ на «уже?» если нет: ยังครับ yang khráp или ยังค่ะ yang khâ."},{"th":"หรือ","rom":"rʉ̌ʉ","ru":"или","how":"ห не читается и делает класс высоким. Звук начинается с r. ื долгое ʉ. Живой слог без знака: восходящий rʉ̌ʉ. หรือยัง «уже или ещё нет»."},{"th":"เคย","rom":"khəəi","ru":"доводилось","how":"ค это kh, низкий класс. เ и ย дают гласный əəi. Знака нет, живой слог: средний khəəi. ไม่เคย «никогда не доводилось». Это опыт, не «вчера»."},{"th":"เพิ่ง","rom":"phə̂ng","ru":"только что","how":"พ это ph, низкий класс. เ и ิ дают гласный ə. ่ май-эк. ง это нг. Низкий класс плюс май-эк: падающий phə̂ng. Стоит перед действием."},{"th":"เสร็จ","rom":"sèt","ru":"закончить","how":"Слышится sèt, низкий. ส высокий класс, краткое э, на конце глухое т. ร почти не читается. จ на конце даёт то глухое т. Короткий глухой слог высокого класса без знака и есть низкий тон."},{"th":"กิน","rom":"gin","ru":"есть","how":"ก читается g: к без выдоха, не kh. ิ краткое и. น это н. Средний класс, слог живой. Тон средний: gin."},{"th":"ไม่","rom":"mâi","ru":"не","how":"ไ пишется слева, это гласный ai. ม это м. ่ это знак май-эк. Низкий класс плюс май-эк дают падающий тон: mâi. Слово стоит прямо перед действием."},{"th":"ใช่","rom":"châi","ru":"да, это так","how":"ช это ch. ใ гласный ai. ่ май-эк. Низкий класс плюс май-эк: падающий châi. На вопрос с ใช่ไหม отвечают ใช่ или ไม่ใช่. На вопрос с глаголом и ไหม повторяют глагол."}],"diagrams":[{"title":"Уже или ещё нет","slots":[{"role":"действие","m":{"th":"กิน","rom":"gin"},"f":{"th":"กิน","rom":"gin"}},{"role":"или ещё","m":{"th":"หรือยัง","rom":"rʉ̌ʉ-yang"},"f":{"th":"หรือยัง","rom":"rʉ̌ʉ-yang"}}]}],"tables":[{"title":"Рис, три опыта","cols":["да","нет","вопрос"],"rows":[{"h":"уже","cells":[{"ru":"Я уже поел.","m":{"th":"ผมกินแล้วครับ","rom":"phǒm gin lɛ́ɛo khráp"},"f":{"th":"ฉันกินแล้วค่ะ","rom":"chǎn gin lɛ́ɛo khâ"}},{"ru":"Я ещё не ел.","m":{"th":"ผมยังไม่กินครับ","rom":"phǒm yang mâi gin khráp"},"f":{"th":"ฉันยังไม่กินค่ะ","rom":"chǎn yang mâi gin khâ"}},{"ru":"Ты уже поел?","m":{"th":"กินหรือยังครับ","rom":"gin rʉ̌ʉ-yang khráp"},"f":{"th":"กินหรือยังคะ","rom":"gin rʉ̌ʉ-yang khá"}}]},{"h":"бывало","cells":[{"ru":"Мне доводилось есть это.","m":{"th":"ผมเคยกินครับ","rom":"phǒm khəəi gin khráp"},"f":{"th":"ฉันเคยกินค่ะ","rom":"chǎn khəəi gin khâ"}},{"ru":"Мне никогда не доводилось есть это.","m":{"th":"ผมไม่เคยกินครับ","rom":"phǒm mâi-khəəi gin khráp"},"f":{"th":"ฉันไม่เคยกินค่ะ","rom":"chǎn mâi-khəəi gin khâ"}},{"ru":"Тебе доводилось есть это?","m":{"th":"คุณเคยกินไหมครับ","rom":"khun khəəi gin mǎi khráp"},"f":{"th":"คุณเคยกินไหมคะ","rom":"khun khəəi gin mǎi khá"}}]},{"h":"только что","cells":[{"ru":"Я только что поел.","m":{"th":"ผมเพิ่งกินครับ","rom":"phǒm phə̂ng gin khráp"},"f":{"th":"ฉันเพิ่งกินค่ะ","rom":"chǎn phə̂ng gin khâ"}},{"ru":"Я ещё не закончил есть.","m":{"th":"ผมยังกินไม่เสร็จครับ","rom":"phǒm yang gin mâi sèt khráp"},"f":{"th":"ฉันยังกินไม่เสร็จค่ะ","rom":"chǎn yang gin mâi sèt khâ"}},{"ru":"Ты только что поел?","m":{"th":"คุณเพิ่งกินไหมครับ","rom":"khun phə̂ng gin mǎi khráp"},"f":{"th":"คุณเพิ่งกินไหมคะ","rom":"khun phə̂ng gin mǎi khá"}}]}]},{"title":"Короткий ответ","cols":["фраза"],"rows":[{"h":"да уже","cells":[{"ru":"Уже.","m":{"th":"แล้วครับ","rom":"lɛ́ɛo khráp"},"f":{"th":"แล้วค่ะ","rom":"lɛ́ɛo khâ"}}]},{"h":"ещё нет","cells":[{"ru":"Ещё нет.","m":{"th":"ยังครับ","rom":"yang khráp"},"f":{"th":"ยังค่ะ","rom":"yang khâ"}}]},{"h":"закончил","cells":[{"ru":"Я закончил есть.","m":{"th":"ผมกินเสร็จแล้วครับ","rom":"phǒm gin sèt lɛ́ɛo khráp"},"f":{"th":"ฉันกินเสร็จแล้วค่ะ","rom":"chǎn gin sèt lɛ́ɛo khâ"}}]}]}],"drills":[{"ru":"Ты уже поел?","m":{"th":"กินหรือยังครับ","rom":"gin rʉ̌ʉ-yang khráp"},"f":{"th":"กินหรือยังคะ","rom":"gin rʉ̌ʉ-yang khá"}},{"ru":"Я уже поел.","m":{"th":"ผมกินแล้วครับ","rom":"phǒm gin lɛ́ɛo khráp"},"f":{"th":"ฉันกินแล้วค่ะ","rom":"chǎn gin lɛ́ɛo khâ"}},{"ru":"Я ещё не ел.","m":{"th":"ผมยังไม่กินครับ","rom":"phǒm yang mâi gin khráp"},"f":{"th":"ฉันยังไม่กินค่ะ","rom":"chǎn yang mâi gin khâ"}},{"ru":"Уже.","m":{"th":"แล้วครับ","rom":"lɛ́ɛo khráp"},"f":{"th":"แล้วค่ะ","rom":"lɛ́ɛo khâ"}},{"ru":"Ещё нет.","m":{"th":"ยังครับ","rom":"yang khráp"},"f":{"th":"ยังค่ะ","rom":"yang khâ"}},{"ru":"Мне никогда не доводилось есть это.","m":{"th":"ผมไม่เคยกินครับ","rom":"phǒm mâi-khəəi gin khráp"},"f":{"th":"ฉันไม่เคยกินค่ะ","rom":"chǎn mâi-khəəi gin khâ"}},{"ru":"Я только что поел.","m":{"th":"ผมเพิ่งกินครับ","rom":"phǒm phə̂ng gin khráp"},"f":{"th":"ฉันเพิ่งกินค่ะ","rom":"chǎn phə̂ng gin khâ"}},{"ru":"Я закончил есть.","m":{"th":"ผมกินเสร็จแล้วครับ","rom":"phǒm gin sèt lɛ́ɛo khráp"},"f":{"th":"ฉันกินเสร็จแล้วค่ะ","rom":"chǎn gin sèt lɛ́ɛo khâ"}}],"self":"Ответьте на «กินหรือยัง» про сегодняшний рис. Потом скажите про одно блюдо, которое ели хоть раз, и одно, которое не ели никогда. «Вчера любил» скажите отдельно, через เมื่อวาน, без แล้ว."},{"id":15,"title":"Попросить и заказать","goal":"Попросить говорить медленнее, заказать рис и воду, попросить счёт и сказать «не надо» и «нельзя».","petrov":"Пятнадцатый шаг Петрова: просьба и запрет. В кафе и в такси работают те же клетки, не отдельный разговорник.","formula":"Мягкая просьба: ช่วย + действие + หน่อย. Заказ: เอา или ขอ. «Можно?»: действие + ได้ไหม. Запрет себе и другому: อย่า перед действием. Жёсткое «нельзя»: ห้าม.","note":"Не острое: ไม่เผ็ด, без связки. Счёт: คิดเงิน. Дверь: ประตู.","lead":{"ru":"Говорите, пожалуйста, медленно.","m":{"th":"ช่วยพูดช้าๆหน่อยครับ","rom":"chûai phûut cháa-cháa nɔ̀i khráp"},"f":{"th":"ช่วยพูดช้าๆหน่อยค่ะ","rom":"chûai phûut cháa-cháa nɔ̀i khâ"}},"words":[{"th":"ช่วย","rom":"chûai","ru":"помочь; в просьбе «будьте добры»","how":"ช низкий класс. ่ май-эк. Гласный uai из ว и ย. Низкий класс плюс май-эк: падающий chûai. ช่วย…หน่อย «сделайте, пожалуйста»."},{"th":"หน่อย","rom":"nɔ̀i","ru":"немного; смягчает просьбу","how":"ห не читается. Звук с н. ่ май-эк. อย гласный oi. Высокий класс плюс май-эк: низкий nɔ̀i. Стоит в конце просьбы, перед ครับ khráp или ค่ะ khâ."},{"th":"ขอ","rom":"khɔ̌ɔ","ru":"прошу","how":"ข высокий класс. อ долгое о. Живой слог без знака: восходящий khɔ̌ɔ. ขอน้ำ «воды, пожалуйста»."},{"th":"อย่า","rom":"yàa","ru":"не делай","how":"อ задаёт средний класс, звук с ย. ่ май-эк. า долгое а. Средний класс плюс май-эк: низкий yàa. Перед действием: อย่าไป «не ходи»."},{"th":"ห้าม","rom":"hâam","ru":"нельзя, запрещено","how":"ห высокий класс, слышна. ้ май-тхо. า долгое а. ม это м. Высокий класс плюс май-тхо: падающий hâam."},{"th":"เอา","rom":"ao","ru":"брать; «мне вот это»","how":"อ средний класс. เ и า дают ao. Живой слог без знака: средний ao. В кафе เอาข้าวผัด «мне жареный рис»."},{"th":"ซื้อ","rom":"sʉ́ʉ","ru":"покупать","how":"ซ это s, низкий класс. ื долгое ʉ. ้ май-тхо. Низкий класс плюс май-тхо: высокий sʉ́ʉ."},{"th":"ให้","rom":"hâi","ru":"дать; сделать для кого-то","how":"ห высокий класс, слышна. ใ гласный ai. ้ май-тхо. Высокий класс плюс май-тхо: падающий hâi. ซื้อน้ำให้ผม «купи воды для меня»."},{"th":"เปิด","rom":"bpə̀ət","ru":"открывать","how":"ป это bp. เ и ิ дают долгий гласный əə. ด глухое т. Знака нет. Долгий глухой слог среднего класса: низкий bpə̀ət."},{"th":"ปิด","rom":"bpìt","ru":"закрывать","how":"ป это bp. ิ краткое и. ด глухое т. Короткий глухой слог среднего класса: низкий bpìt."},{"th":"ประตู","rom":"bprà-dtuu","ru":"дверь","how":"ประ: ป и ร дают bpr, ะ краткое а. Короткий слог среднего класса: низкий bprà. ตู: ต это dt, ู долгое у, средний dtuu."},{"th":"คิด","rom":"khít","ru":"считать, думать","how":"ค это kh, низкий класс. ิ краткое и. ด глухое т. Короткий глухой слог низкого класса: высокий khít. คิดเงิน «посчитать деньги, принести счёт»."},{"th":"เงิน","rom":"ngən","ru":"деньги","how":"ง начинает слог, это ng. เ и ิ дают гласный ə. น это н. Низкий класс, живой слог: средний ngən."},{"th":"ผัด","rom":"phàt","ru":"жареный","how":"ผ это ph, высокий класс. ั краткое а. ด глухое т. Короткий глухой слог высокого класса: низкий phàt. ข้าวผัด «жареный рис»: khâao-phàt."},{"th":"เผ็ด","rom":"phèt","ru":"острый","how":"ผ высокий класс. เ и ็ краткое э. ด глухое т. Короткий глухой слог высокого класса: низкий phèt. ไม่เผ็ด «не острое»."},{"th":"ข้าว","rom":"khâao","ru":"рис, еда","how":"ข это kh, высокий класс. ้ май-тхо. า долгое а, ว достраивает гласный ao. Высокий класс плюс май-тхо: падающий khâao."},{"th":"น้ำ","rom":"náam","ru":"вода","how":"น низкий класс. ้ май-тхо. ำ это долгое ам. Низкий класс плюс май-тхо: высокий náam."},{"th":"พูด","rom":"phûut","ru":"говорить","how":"พ это ph, низкий класс. ู долгое у. ด на конце глухое т. Знака тона нет. Долгий глухой слог низкого класса: падающий phûut."},{"th":"ช้า","rom":"cháa","ru":"медленно","how":"ช это ch, низкий класс. ้ май-тхо. า долгое а. Низкий класс плюс май-тхо: высокий cháa. Повтор ช้าๆ значит «медленно, потихоньку»: cháa-cháa."},{"th":"ได้","rom":"dâai","ru":"получилось; в ไม่ได้ меняет смысл от места","how":"ไ слева, гласный ai. ด это d. ้ это май-тхо. Средний класс плюс май-тхо дают падающий тон: dâai. Перед действием ไม่ได้ значит «не сделал». После действия ได้ значит «могу», ไม่ได้ значит «не могу»."},{"th":"ไหม","rom":"mǎi","ru":"ли, вопрос да или нет","how":"ห не читается: она только переводит слог в высокий класс. Звук начинается с м, гласный тот же ai, что в ไม่. Знака тона нет. Высокий класс и живой слог дают восходящий тон: mǎi. Стоит в конце фразы, перед ครับ khráp или คะ khá. С падающим ไม่ это разные слова."}],"diagrams":[{"title":"Заказ","slots":[{"role":"беру","m":{"th":"เอา","rom":"ao"},"f":{"th":"เอา","rom":"ao"}},{"role":"что","m":{"th":"ข้าวผัด","rom":"khâao-phàt"},"f":{"th":"ข้าวผัด","rom":"khâao-phàt"}},{"role":"не так","m":{"th":"ไม่เผ็ด","rom":"mâi phèt"},"f":{"th":"ไม่เผ็ด","rom":"mâi phèt"}}]}],"tables":[{"title":"Попросить","cols":["просьба","не так","можно?"],"rows":[{"h":"речь","cells":[{"ru":"Говорите, пожалуйста, медленно.","m":{"th":"ช่วยพูดช้าๆหน่อยครับ","rom":"chûai phûut cháa-cháa nɔ̀i khráp"},"f":{"th":"ช่วยพูดช้าๆหน่อยค่ะ","rom":"chûai phûut cháa-cháa nɔ̀i khâ"}},{"ru":"Не говорите.","m":{"th":"อย่าพูดครับ","rom":"yàa phûut khráp"},"f":{"th":"อย่าพูดค่ะ","rom":"yàa phûut khâ"}},{"ru":"Можно ещё раз?","m":{"th":"พูดอีกทีได้ไหมครับ","rom":"phûut ìik-thii dâai mǎi khráp"},"f":{"th":"พูดอีกทีได้ไหมคะ","rom":"phûut ìik-thii dâai mǎi khá"}}]},{"h":"рис","cells":[{"ru":"Мне жареный рис.","m":{"th":"เอาข้าวผัดครับ","rom":"ao khâao-phàt khráp"},"f":{"th":"เอาข้าวผัดค่ะ","rom":"ao khâao-phàt khâ"}},{"ru":"Не остро.","m":{"th":"ไม่เผ็ดครับ","rom":"mâi phèt khráp"},"f":{"th":"ไม่เผ็ดค่ะ","rom":"mâi phèt khâ"}},{"ru":"Можно жареный рис?","m":{"th":"เอาข้าวผัดได้ไหมครับ","rom":"ao khâao-phàt dâai mǎi khráp"},"f":{"th":"เอาข้าวผัดได้ไหมคะ","rom":"ao khâao-phàt dâai mǎi khá"}}]},{"h":"вода","cells":[{"ru":"Воды, пожалуйста.","m":{"th":"ขอน้ำครับ","rom":"khɔ̌ɔ náam khráp"},"f":{"th":"ขอน้ำค่ะ","rom":"khɔ̌ɔ náam khâ"}},{"ru":"Воды не надо.","m":{"th":"ไม่เอาน้ำครับ","rom":"mâi ao náam khráp"},"f":{"th":"ไม่เอาน้ำค่ะ","rom":"mâi ao náam khâ"}},{"ru":"Можно воды?","m":{"th":"ขอน้ำได้ไหมครับ","rom":"khɔ̌ɔ náam dâai mǎi khráp"},"f":{"th":"ขอน้ำได้ไหมคะ","rom":"khɔ̌ɔ náam dâai mǎi khá"}}]},{"h":"дверь","cells":[{"ru":"Откройте, пожалуйста, дверь.","m":{"th":"ช่วยเปิดประตูหน่อยครับ","rom":"chûai bpə̀ət bprà-dtuu nɔ̀i khráp"},"f":{"th":"ช่วยเปิดประตูหน่อยค่ะ","rom":"chûai bpə̀ət bprà-dtuu nɔ̀i khâ"}},{"ru":"Не открывайте дверь.","m":{"th":"อย่าเปิดประตูครับ","rom":"yàa bpə̀ət bprà-dtuu khráp"},"f":{"th":"อย่าเปิดประตูค่ะ","rom":"yàa bpə̀ət bprà-dtuu khâ"}},{"ru":"Можно открыть дверь?","m":{"th":"เปิดประตูได้ไหมครับ","rom":"bpə̀ət bprà-dtuu dâai mǎi khráp"},"f":{"th":"เปิดประตูได้ไหมคะ","rom":"bpə̀ət bprà-dtuu dâai mǎi khá"}}]},{"h":"счёт","cells":[{"ru":"Посчитайте, пожалуйста.","m":{"th":"คิดเงินหน่อยครับ","rom":"khít ngən nɔ̀i khráp"},"f":{"th":"คิดเงินหน่อยค่ะ","rom":"khít ngən nɔ̀i khâ"}},{"ru":"Есть нельзя.","m":{"th":"ห้ามกินครับ","rom":"hâam gin khráp"},"f":{"th":"ห้ามกินค่ะ","rom":"hâam gin khâ"}},{"ru":"Можно счёт?","m":{"th":"คิดเงินได้ไหมครับ","rom":"khít ngən dâai mǎi khráp"},"f":{"th":"คิดเงินได้ไหมคะ","rom":"khít ngən dâai mǎi khá"}}]}]}],"drills":[{"ru":"Говорите, пожалуйста, медленно.","m":{"th":"ช่วยพูดช้าๆหน่อยครับ","rom":"chûai phûut cháa-cháa nɔ̀i khráp"},"f":{"th":"ช่วยพูดช้าๆหน่อยค่ะ","rom":"chûai phûut cháa-cháa nɔ̀i khâ"}},{"ru":"Мне жареный рис.","m":{"th":"เอาข้าวผัดครับ","rom":"ao khâao-phàt khráp"},"f":{"th":"เอาข้าวผัดค่ะ","rom":"ao khâao-phàt khâ"}},{"ru":"Не остро.","m":{"th":"ไม่เผ็ดครับ","rom":"mâi phèt khráp"},"f":{"th":"ไม่เผ็ดค่ะ","rom":"mâi phèt khâ"}},{"ru":"Воды, пожалуйста.","m":{"th":"ขอน้ำครับ","rom":"khɔ̌ɔ náam khráp"},"f":{"th":"ขอน้ำค่ะ","rom":"khɔ̌ɔ náam khâ"}},{"ru":"Можно счёт?","m":{"th":"คิดเงินได้ไหมครับ","rom":"khít ngən dâai mǎi khráp"},"f":{"th":"คิดเงินได้ไหมคะ","rom":"khít ngən dâai mǎi khá"}},{"ru":"Откройте, пожалуйста, дверь.","m":{"th":"ช่วยเปิดประตูหน่อยครับ","rom":"chûai bpə̀ət bprà-dtuu nɔ̀i khráp"},"f":{"th":"ช่วยเปิดประตูหน่อยค่ะ","rom":"chûai bpə̀ət bprà-dtuu nɔ̀i khâ"}},{"ru":"Не открывайте дверь.","m":{"th":"อย่าเปิดประตูครับ","rom":"yàa bpə̀ət bprà-dtuu khráp"},"f":{"th":"อย่าเปิดประตูค่ะ","rom":"yàa bpə̀ət bprà-dtuu khâ"}},{"ru":"Есть нельзя.","m":{"th":"ห้ามกินครับ","rom":"hâam gin khráp"},"f":{"th":"ห้ามกินค่ะ","rom":"hâam gin khâ"}}],"self":"Соберите заказ, который сделали бы сегодня: что берёте, чего не хотите, и попросите счёт. Потом одну запрещающую фразу через อย่า."},{"id":16,"title":"Связать действия и рассказать о себе","goal":"Сказать «сходи купи», «купи и принеси», «купи для меня» и связать это в короткий рассказ о своём дне.","petrov":"Шестнадцатый шаг Петрова: действия, которые в английском были бы фразовыми глаголами. В тайском глагол ставится к глаголу. Потом вы рассказываете своими фразами из всех шестнадцати уроков.","formula":"ไปซื้อ «иди купи». ซื้อ…มา «купи и принеси сюда». ซื้อ…ให้ «купи для». แล้วก็ «а потом». เลย «поэтому». Я тоже: ผมด้วย.","note":"Ниже шестнадцать проверок, по одной на урок. Скажите вслух до того, как откроете ответ. Если клетка не собирается, вернитесь только в тот урок: схема одна, слова те же.","lead":{"ru":"Сходи купи мне воды.","m":{"th":"ไปซื้อน้ำให้ผมครับ","rom":"bpai sʉ́ʉ náam hâi phǒm khráp"},"f":{"th":"ไปซื้อน้ำให้ฉันค่ะ","rom":"bpai sʉ́ʉ náam hâi chǎn khâ"}},"words":[{"th":"ไป","rom":"bpai","ru":"идти, ехать туда","how":"ป читается bp: п без выдоха, один звук. ไ гласный ai. Средний класс, живой слог, знака нет: средний bpai."},{"th":"ซื้อ","rom":"sʉ́ʉ","ru":"покупать","how":"ซ это s, низкий класс. ื долгое ʉ. ้ май-тхо. Низкий класс плюс май-тхо: высокий sʉ́ʉ."},{"th":"น้ำ","rom":"náam","ru":"вода","how":"น низкий класс. ้ май-тхо. ำ это долгое ам. Низкий класс плюс май-тхо: высокий náam."},{"th":"ให้","rom":"hâi","ru":"дать; сделать для кого-то","how":"ห высокий класс, слышна. ใ гласный ai. ้ май-тхо. Высокий класс плюс май-тхо: падающий hâi. ซื้อน้ำให้ผม «купи воды для меня»."},{"th":"มา","rom":"maa","ru":"приходить, сюда","how":"ม это м, низкий класс. า долгое а. Знака нет, живой слог: средний maa. Рядом с другим глаголом показывает направление к говорящему."},{"th":"เอา","rom":"ao","ru":"брать; «мне вот это»","how":"อ средний класс. เ и า дают ao. Живой слог без знака: средний ao. В кафе เอาข้าวผัด «мне жареный рис»."},{"th":"แล้ว","rom":"lɛ́ɛo","ru":"уже","how":"ล низкий класс. แ долгое открытое э. ้ май-тхо. ว достраивает гласный. Низкий класс плюс май-тхо: высокий lɛ́ɛo. Это не окончание прошедшего времени. Смысл: дело дошло до новой точки, «уже»."},{"th":"ก็","rom":"gɔ̂","ru":"тогда, и вот","how":"На письме ก и знак краткости ็. Отдельного знака тона нет, но слово читается падающим: gɔ̂. Конец коротко обрывается. Тон запомните вместе со словом. В แล้วก็ «а потом» второе слово то же."},{"th":"เลย","rom":"ləəi","ru":"поэтому, тогда и","how":"ล низкий класс. เ и ย дают гласный əəi. Знака нет, живой слог: средний ləəi. После причины: หิวเลยไปกิน «голоден, поэтому иду есть»."},{"th":"กลับ","rom":"glàp","ru":"возвращаться","how":"ก и ล вместе gl. ั краткое а. บ глухое п. Средний класс, короткий глухой слог: низкий glàp."},{"th":"บ้าน","rom":"bâan","ru":"дом","how":"บ это b, средний класс. ้ май-тхо. า долгое а. น это н. Средний класс плюс май-тхо: падающий bâan."},{"th":"หิว","rom":"hǐu","ru":"голодный","how":"ห это h, высокий класс, здесь она слышна. ิ краткое и. ว закрывает слог на w. Знака нет, живой слог высокого класса: восходящий hǐu. Перед ним нет связки: ผมหิว «я голоден»."},{"th":"กิน","rom":"gin","ru":"есть","how":"ก читается g: к без выдоха, не kh. ิ краткое и. น это н. Средний класс, слог живой. Тон средний: gin."},{"th":"ด้วย","rom":"dûai","ru":"тоже","how":"ด средний класс. ้ май-тхо, не май-эк. ว и ย дают гласный uai. Средний класс плюс май-тхо: падающий dûai."}],"diagrams":[{"title":"Купи для меня","slots":[{"role":"иди","m":{"th":"ไป","rom":"bpai"},"f":{"th":"ไป","rom":"bpai"}},{"role":"купи","m":{"th":"ซื้อ","rom":"sʉ́ʉ"},"f":{"th":"ซื้อ","rom":"sʉ́ʉ"}},{"role":"что","m":{"th":"น้ำ","rom":"náam"},"f":{"th":"น้ำ","rom":"náam"}},{"role":"для","m":{"th":"ให้","rom":"hâi"},"f":{"th":"ให้","rom":"hâi"}},{"role":"кого","m":{"th":"ผม","rom":"phǒm"},"f":{"th":"ฉัน","rom":"chǎn"}}]}],"tables":[{"title":"Два глагола подряд","cols":["фраза"],"rows":[{"h":"иди купи","cells":[{"ru":"Сходи купи воды.","m":{"th":"ไปซื้อน้ำครับ","rom":"bpai sʉ́ʉ náam khráp"},"f":{"th":"ไปซื้อน้ำค่ะ","rom":"bpai sʉ́ʉ náam khâ"}}]},{"h":"принеси","cells":[{"ru":"Купи воды и принеси.","m":{"th":"ซื้อน้ำมาครับ","rom":"sʉ́ʉ náam maa khráp"},"f":{"th":"ซื้อน้ำมาค่ะ","rom":"sʉ́ʉ náam maa khâ"}}]},{"h":"для меня","cells":[{"ru":"Купи воды для меня.","m":{"th":"ซื้อน้ำให้ผมครับ","rom":"sʉ́ʉ náam hâi phǒm khráp"},"f":{"th":"ซื้อน้ำให้ฉันค่ะ","rom":"sʉ́ʉ náam hâi chǎn khâ"}}]},{"h":"а потом","cells":[{"ru":"Я пойду куплю воды, а потом вернусь домой.","m":{"th":"ผมไปซื้อน้ำแล้วก็กลับบ้านครับ","rom":"phǒm bpai sʉ́ʉ náam lɛ́ɛo gɔ̂ glàp bâan khráp"},"f":{"th":"ฉันไปซื้อน้ำแล้วก็กลับบ้านค่ะ","rom":"chǎn bpai sʉ́ʉ náam lɛ́ɛo gɔ̂ glàp bâan khâ"}}]},{"h":"поэтому","cells":[{"ru":"Я голоден, поэтому иду есть.","m":{"th":"ผมหิวเลยไปกินครับ","rom":"phǒm hǐu ləəi bpai gin khráp"},"f":{"th":"ฉันหิวเลยไปกินค่ะ","rom":"chǎn hǐu ləəi bpai gin khâ"}}]},{"h":"я тоже","cells":[{"ru":"Я тоже.","m":{"th":"ผมด้วยครับ","rom":"phǒm dûai khráp"},"f":{"th":"ฉันด้วยค่ะ","rom":"chǎn dûai khâ"}}]}]}],"drills":[{"ru":"Завтра я буду любить тебя.","m":{"th":"พรุ่งนี้ผมจะรักคุณครับ","rom":"phrûng-níi phǒm jà rák khun khráp"},"f":{"th":"พรุ่งนี้ฉันจะรักคุณค่ะ","rom":"phrûng-níi chǎn jà rák khun khâ"}},{"ru":"Что ты ешь?","m":{"th":"คุณกินอะไรครับ","rom":"khun gin à-rai khráp"},"f":{"th":"คุณกินอะไรคะ","rom":"khun gin à-rai khá"}},{"ru":"Я дома и хочу есть.","m":{"th":"ผมอยู่บ้านครับ ผมอยากกินครับ","rom":"phǒm yùu bâan khráp phǒm yàak gin khráp"},"f":{"th":"ฉันอยู่บ้านค่ะ ฉันอยากกินค่ะ","rom":"chǎn yùu bâan khâ chǎn yàak gin khâ"}},{"ru":"Это мой дом.","m":{"th":"นี่บ้านผมครับ","rom":"nîi bâan phǒm khráp"},"f":{"th":"นี่บ้านฉันค่ะ","rom":"nîi bâan chǎn khâ"}},{"ru":"Я не понимаю. Скажите ещё раз?","m":{"th":"ไม่เข้าใจครับ พูดอีกทีได้ไหมครับ","rom":"mâi khâo-jai khráp phûut ìik-thii dâai mǎi khráp"},"f":{"th":"ไม่เข้าใจค่ะ พูดอีกทีได้ไหมคะ","rom":"mâi khâo-jai khâ phûut ìik-thii dâai mǎi khá"}},{"ru":"Вот это дешевле, чем то.","m":{"th":"อันนี้ถูกกว่าอันนั้นครับ","rom":"an-níi thùuk gwàa an-nán khráp"},"f":{"th":"อันนี้ถูกกว่าอันนั้นค่ะ","rom":"an-níi thùuk gwàa an-nán khâ"}},{"ru":"Два стакана воды. Сколько это стоит?","m":{"th":"น้ำสองแก้วครับ อันนี้กี่บาทครับ","rom":"náam sɔ̌ɔng gâeo khráp an-níi gìi bàat khráp"},"f":{"th":"น้ำสองแก้วค่ะ อันนี้กี่บาทคะ","rom":"náam sɔ̌ɔng gâeo khâ an-níi gìi bàat khá"}},{"ru":"Сейчас восемь утра.","m":{"th":"ตอนนี้แปดโมงเช้าครับ","rom":"dtɔɔn-níi bpɛ̀ɛt moong cháao khráp"},"f":{"th":"ตอนนี้แปดโมงเช้าค่ะ","rom":"dtɔɔn-níi bpɛ̀ɛt moong cháao khâ"}},{"ru":"Здесь есть вода?","m":{"th":"ที่นี่มีน้ำไหมครับ","rom":"thîi-nîi mii náam mǎi khráp"},"f":{"th":"ที่นี่มีน้ำไหมคะ","rom":"thîi-nîi mii náam mǎi khá"}},{"ru":"Налево.","m":{"th":"เลี้ยวซ้ายครับ","rom":"líao sáai khráp"},"f":{"th":"เลี้ยวซ้ายค่ะ","rom":"líao sáai khâ"}},{"ru":"Я не могу пойти, но мне надо пойти.","m":{"th":"ผมไปไม่ได้ครับ แต่ผมต้องไปครับ","rom":"phǒm bpai mâi-dâai khráp dtɛ̀ɛ phǒm dtɔ̂ɔng bpai khráp"},"f":{"th":"ฉันไปไม่ได้ค่ะ แต่ฉันต้องไปค่ะ","rom":"chǎn bpai mâi-dâai khâ dtɛ̀ɛ chǎn dtɔ̂ɔng bpai khâ"}},{"ru":"Я сейчас ем.","m":{"th":"ตอนนี้ผมกำลังกินอยู่ครับ","rom":"dtɔɔn-níi phǒm gam-lang gin yùu khráp"},"f":{"th":"ตอนนี้ฉันกำลังกินอยู่ค่ะ","rom":"dtɔɔn-níi chǎn gam-lang gin yùu khâ"}},{"ru":"Сегодня жарко, я устал.","m":{"th":"วันนี้ร้อนครับ ผมเหนื่อยครับ","rom":"wan-níi rɔ́ɔn khráp phǒm nʉ̀ai khráp"},"f":{"th":"วันนี้ร้อนค่ะ ฉันเหนื่อยค่ะ","rom":"wan-níi rɔ́ɔn khâ chǎn nʉ̀ai khâ"}},{"ru":"Я ещё не ел.","m":{"th":"ผมยังไม่กินครับ","rom":"phǒm yang mâi gin khráp"},"f":{"th":"ฉันยังไม่กินค่ะ","rom":"chǎn yang mâi gin khâ"}},{"ru":"Мне жареный рис, не острый.","m":{"th":"เอาข้าวผัด ไม่เผ็ดครับ","rom":"ao khâao-phàt mâi phèt khráp"},"f":{"th":"เอาข้าวผัด ไม่เผ็ดค่ะ","rom":"ao khâao-phàt mâi phèt khâ"}},{"ru":"Сходи купи мне воды.","m":{"th":"ไปซื้อน้ำให้ผมครับ","rom":"bpai sʉ́ʉ náam hâi phǒm khráp"},"f":{"th":"ไปซื้อน้ำให้ฉันค่ะ","rom":"bpai sʉ́ʉ náam hâi chǎn khâ"}}],"self":"Расскажите шесть фраз о сегодняшнем дне: куда пошли, что купили, для кого, что уже сделали, чего ещё нет и что будете делать завтра. Глаголы ставьте подряд, время оставляйте рамкой."}]
